insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7250d146-cfd3-58c7-8e25-4ce7b3153b93', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '367', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَسُرَيْجُ بْنُ يُونُسَ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَعَلِيُّ بْنُ حُجْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى الْمَقْبُرَةَ فَقَالَ ‏ ‏السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ وَدِدْتُ أَنَّا قَدْ رَأَيْنَا إِخْوَانَنَا قَالُوا أَوَلَسْنَا إِخْوَانَكَ يَا رَسُولَ اللَّهِ قَالَ أَنْتُمْ أَصْحَابِي وَإِخْوَانُنَا الَّذِينَ لَمْ يَأْتُوا بَعْدُ فَقَالُوا كَيْفَ تَعْرِفُ مَنْ لَمْ يَأْتِ بَعْدُ مِنْ أُمَّتِكَ يَا رَسُولَ اللَّهِ فَقَالَ أَرَأَيْتَ لَوْ أَنَّ رَجُلًا لَهُ خَيْلٌ غُرٌّ ‏ ‏مُحَجَّلَةٌ ‏ ‏بَيْنَ ظَهْرَيْ خَيْلٍ ‏ ‏دُهْمٍ ‏ ‏بُهْمٍ ‏ ‏أَلَا يَعْرِفُ خَيْلَهُ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَإِنَّهُمْ يَأْتُونَ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ الْوُضُوءِ وَأَنَا ‏ ‏فَرَطُهُمْ ‏ ‏عَلَى الْحَوْضِ أَلَا ‏ ‏لَيُذَادَنَّ ‏ ‏رِجَالٌ عَنْ حَوْضِي كَمَا ‏ ‏يُذَادُ ‏ ‏الْبَعِيرُ الضَّالُّ ‏ ‏أُنَادِيهِمْ أَلَا ‏ ‏هَلُمَّ ‏ ‏فَيُقَالُ إِنَّهُمْ قَدْ بَدَّلُوا بَعْدَكَ فَأَقُولُ ‏ ‏سُحْقًا ‏ ‏سُحْقًا ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي الدَّرَاوَرْدِيَّ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الْمَقْبُرَةِ فَقَالَ السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ بِمِثْلِ حَدِيثِ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏غَيْرَ أَنَّ حَدِيثَ ‏ ‏مَالِكٍ ‏ ‏فَلَيُذَادَنَّ ‏ ‏رِجَالٌ عَنْ حَوْضِي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
