insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('638b4afe-e240-5751-9250-2c374db71145', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '369', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ ‏ ‏وَابْنُ حُجْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أَدُلُّكُمْ عَلَى مَا ‏ ‏يَمْحُو اللَّهُ بِهِ الْخَطَايَا وَيَرْفَعُ بِهِ الدَّرَجَاتِ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِسْبَاغُ ‏ ‏الْوُضُوءِ عَلَى ‏ ‏الْمَكَارِهِ ‏ ‏وَكَثْرَةُ ‏ ‏الْخُطَا إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَلَيْسَ فِي حَدِيثِ ‏ ‏شُعْبَةَ ‏ ‏ذِكْرُ ‏ ‏الرِّبَاطِ ‏ ‏وَفِي حَدِيثِ ‏ ‏مَالِكٍ ‏ ‏ثِنْتَيْنِ فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('be513eb8-a82b-5207-babd-5d7612b816c3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '370', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى الْمُؤْمِنِينَ ‏ ‏وَفِي حَدِيثِ ‏ ‏زُهَيْرٍ ‏ ‏عَلَى أُمَّتِي ‏ ‏لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b13b7e4a-6988-55f3-8b4e-13a51b731812', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '371', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏قُلْتُ ‏ ‏بِأَيِّ شَيْءٍ كَانَ يَبْدَأُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ بَيْتَهُ قَالَتْ بِالسِّوَاكِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7bf7b8ad-8130-58bd-8d54-4577178d68bc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '372', '‏ ‏و حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ نَافِعٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا دَخَلَ بَيْتَهُ بَدَأَ بِالسِّوَاكِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0578ad23-1929-531b-be8c-1d391c8887c6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '373', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏غَيْلَانَ وَهُوَ ابْنُ جَرِيرٍ الْمَعْوَلِيُّ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَطَرَفُ السِّوَاكِ عَلَى لِسَانِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6576a016-9bf6-5fc0-90a9-3c340b375960', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '374', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ لِيَتَهَجَّدَ ‏ ‏يَشُوصُ ‏ ‏فَاهُ بِالسِّوَاكِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ مِنْ اللَّيْلِ بِمِثْلِهِ وَلَمْ يَقُولُوا لِيَتَهَجَّدَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d3bcbfb6-0924-50f8-a654-616f820a03e7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '375', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَحُصَيْنٌ ‏ ‏وَالْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا قَامَ مِنْ اللَّيْلِ يَشُوصُ فَاهُ بِالسِّوَاكِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4e99ab1b-06ce-5b7e-902c-4239f10d4c2c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '376', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ بَاتَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَقَامَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ آخِرِ اللَّيْلِ فَخَرَجَ فَنَظَرَ فِي السَّمَاءِ ثُمَّ تَلَا هَذِهِ الْآيَةَ فِي ‏ ‏آلِ ‏ ‏عِمْرَانَ ‏ { ‏إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ ‏ ‏حَتَّى بَلَغَ ‏ ‏فَقِنَا عَذَابَ النَّارِ ‏} ‏ثُمَّ رَجَعَ إِلَى الْبَيْتِ فَتَسَوَّكَ وَتَوَضَّأَ ثُمَّ قَامَ فَصَلَّى ثُمَّ اضْطَجَعَ ثُمَّ قَامَ فَخَرَجَ فَنَظَرَ إِلَى السَّمَاءِ فَتَلَا هَذِهِ الْآيَةَ ثُمَّ رَجَعَ فَتَسَوَّكَ فَتَوَضَّأَ ثُمَّ قَامَ فَصَلَّى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1a28deab-6981-5e87-bebc-f71a5423d207', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '377', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْفِطْرَةُ خَمْسٌ أَوْ ‏ ‏خَمْسٌ مِنْ الْفِطْرَةِ ‏ ‏الْخِتَانُ ‏ ‏وَالِاسْتِحْدَادُ ‏ ‏وَتَقْلِيمُ الْأَظْفَارِ وَنَتْفُ الْإِبِطِ وَقَصُّ الشَّارِبِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8a12e628-d512-5896-b9dc-ac5c35cfb1d4', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '378', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏وَحَرْمَلَةُ بْنُ يَحْيَى ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْفِطْرَةُ خَمْسٌ ‏ ‏الِاخْتِتَانُ ‏ ‏وَالِاسْتِحْدَادُ ‏ ‏وَقَصُّ الشَّارِبِ وَتَقْلِيمُ الْأَظْفَارِ وَنَتْفُ الْإِبِطِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('763ccde6-a3cc-571e-a7c4-52b72d7c3b14', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '379', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏وُقِّتَ لَنَا فِي قَصِّ الشَّارِبِ وَتَقْلِيمِ الْأَظْفَارِ وَنَتْفِ الْإِبِطِ وَحَلْقِ ‏ ‏الْعَانَةِ ‏ ‏أَنْ لَا نَتْرُكَ أَكْثَرَ مِنْ أَرْبَعِينَ لَيْلَةً ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a6cda7f9-0177-5410-bb76-e6b3912c7904', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '380', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَحْفُوا ‏ ‏الشَّوَارِبَ وَأَعْفُوا اللِّحَى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('84f3dea7-4835-5cca-b98a-79cd76e6b001', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '381', '‏ ‏و حَدَّثَنَاه ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَمَرَ ‏ ‏بِإِحْفَاءِ ‏ ‏الشَّوَارِبِ وَإِعْفَاءِ اللِّحْيَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0476be84-5bcd-5106-85d4-13313e323d59', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '382', '‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَالِفُوا الْمُشْرِكِينَ ‏ ‏أَحْفُوا ‏ ‏الشَّوَارِبَ ‏ ‏وَأَوْفُوا ‏ ‏اللِّحَى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5d190611-9e92-5160-8f1d-fe53aac36fb2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '383', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ إِسْحَقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي مَرْيَمَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏مَوْلَى الْحُرَقَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُزُّوا ‏ ‏الشَّوَارِبَ وَأَرْخُوا اللِّحَى خَالِفُوا ‏ ‏الْمَجُوسَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cf5759d1-18c7-52b6-84c6-2abbece05166', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '384', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏زَكَرِيَّاءَ بْنِ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرٌ مِنْ الْفِطْرَةِ قَصُّ الشَّارِبِ وَإِعْفَاءُ اللِّحْيَةِ وَالسِّوَاكُ وَاسْتِنْشَاقُ الْمَاءِ وَقَصُّ الْأَظْفَارِ وَغَسْلُ ‏ ‏الْبَرَاجِمِ ‏ ‏وَنَتْفُ الْإِبِطِ وَحَلْقُ ‏ ‏الْعَانَةِ ‏ ‏وَانْتِقَاصُ الْمَاءِ ‏ ‏قَالَ ‏ ‏زَكَرِيَّاءُ ‏ ‏قَالَ ‏ ‏مُصْعَبٌ ‏ ‏وَنَسِيتُ الْعَاشِرَةَ إِلَّا أَنْ تَكُونَ الْمَضْمَضَةَ ‏ ‏زَادَ ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏انْتِقَاصُ الْمَاءِ ‏ ‏يَعْنِي ‏ ‏الِاسْتِنْجَاءَ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو كُرَيْبٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ شَيْبَةَ ‏ ‏فِي هَذَا الْإِسْنَادِ مِثْلَهُ غَيْرَ أَنَّهُ قَالَ قَالَ أَبُوهُ وَنَسِيتُ الْعَاشِرَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9543f42f-c019-543f-8876-f0b8fefb2429', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '385', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ ‏ ‏قِيلَ لَهُ قَدْ عَلَّمَكُمْ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلَّ شَيْءٍ حَتَّى الْخِرَاءَةَ قَالَ فَقَالَ أَجَلْ لَقَدْ ‏ ‏نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ لِغَائِطٍ أَوْ بَوْلٍ أَوْ أَنْ ‏ ‏نَسْتَنْجِيَ ‏ ‏بِالْيَمِينِ أَوْ أَنْ ‏ ‏نَسْتَنْجِيَ ‏ ‏بِأَقَلَّ مِنْ ثَلَاثَةِ أَحْجَارٍ أَوْ أَنْ ‏ ‏نَسْتَنْجِيَ ‏ ‏بِرَجِيعٍ ‏ ‏أَوْ بِعَظْمٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('14795305-9005-5246-a181-528f49c50f31', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '386', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا الْمُشْرِكُونَ إِنِّي أَرَى صَاحِبَكُمْ يُعَلِّمُكُمْ حَتَّى يُعَلِّمَكُمْ الْخِرَاءَةَ فَقَالَ أَجَلْ إِنَّهُ نَهَانَا أَنْ ‏ ‏يَسْتَنْجِيَ ‏ ‏أَحَدُنَا بِيَمِينِهِ أَوْ يَسْتَقْبِلَ الْقِبْلَةَ وَنَهَى عَنْ الرَّوْثِ وَالْعِظَامِ وَقَالَ ‏ ‏لَا ‏ ‏يَسْتَنْجِي ‏ ‏أَحَدُكُمْ بِدُونِ ثَلَاثَةِ أَحْجَارٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8bf66072-bb66-57e9-9ed3-49856805a537', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '387', '‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ بْنُ إِسْحَقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُا ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُتَمَسَّحَ بِعَظْمٍ أَوْ بِبَعْرٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3d8ff734-62e3-5f40-a6d4-7749455b4df5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '388', '‏ ‏و حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏قَالَ قُلْتُ ‏ ‏لِسُفْيَانَ بْنِ عُيَيْنَةَ ‏ ‏سَمِعْتَ ‏ ‏الزُّهْرِيَّ ‏ ‏يَذْكُرُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَيْتُمْ الْغَائِطَ فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ وَلَا تَسْتَدْبِرُوهَا بِبَوْلٍ وَلَا غَائِطٍ وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَقَدِمْنَا ‏ ‏الشَّامَ ‏ ‏فَوَجَدْنَا مَرَاحِيضَ قَدْ بُنِيَتْ قِبَلَ الْقِبْلَةِ فَنَنْحَرِفُ عَنْهَا وَنَسْتَغْفِرُ اللَّهَ قَالَ نَعَمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d8b0e88f-8d69-5e10-8f04-12a82f9250b0', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '389', '‏ ‏و حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَسَنِ بْنِ خِرَاشٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عَبْدِ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَلَسَ أَحَدُكُمْ عَلَى حَاجَتِهِ فَلَا يَسْتَقْبِلْ الْقِبْلَةَ وَلَا يَسْتَدْبِرْهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2953fe73-a1d4-5c85-b69e-dd3b270ef025', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '390', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ بْنِ قَعْنَبٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏قَالَ ‏ ‏كُنْتُ أُصَلِّي فِي الْمَسْجِدِ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏مُسْنِدٌ ظَهْرَهُ إِلَى الْقِبْلَةِ فَلَمَّا قَضَيْتُ صَلَاتِي انْصَرَفْتُ إِلَيْهِ مِنْ شِقِّي ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَقُولُ نَاسٌ إِذَا قَعَدْتَ لِلْحَاجَةِ تَكُونُ لَكَ فَلَا تَقْعُدْ مُسْتَقْبِلَ الْقِبْلَةِ وَلَا ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَلَقَدْ ‏ ‏رَقِيتُ ‏ ‏عَلَى ظَهْرِ بَيْتٍ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاعِدًا عَلَى لَبِنَتَيْنِ مُسْتَقْبِلًا ‏ ‏بَيْتَ الْمَقْدِسِ ‏ ‏لِحَاجَتِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('220d5942-82fc-55c0-981f-5046017c1e38', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '391', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَقِيتُ عَلَى بَيْتِ أُخْتِي ‏ ‏حَفْصَةَ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاعِدًا لِحَاجَتِهِ مُسْتَقْبِلَ ‏ ‏الشَّامِ ‏ ‏مُسْتَدْبِرَ الْقِبْلَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b644246e-f577-5f09-bf4b-e54ad4bb17b9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '392', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُمْسِكَنَّ أَحَدُكُمْ ذَكَرَهُ بِيَمِينِهِ وَهُوَ يَبُولُ وَلَا يَتَمَسَّحْ مِنْ الْخَلَاءِ بِيَمِينِهِ وَلَا يَتَنَفَّسْ فِي الْإِنَاءِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8e5bec41-d11e-590c-8b1b-98945b1e9cc6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '393', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتَوَائِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْخَلَاءَ فَلَا يَمَسَّ ذَكَرَهُ بِيَمِينِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a89f2e67-e716-5be9-9ff2-90581f8b8d27', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '394', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَتَنَفَّسَ فِي الْإِنَاءِ وَأَنْ يَمَسَّ ذَكَرَهُ بِيَمِينِهِ وَأَنْ ‏ ‏يَسْتَطِيبَ ‏ ‏بِيَمِينِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('166d337d-3a7c-5d2d-984a-00c4c9310d8b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '395', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُحِبُّ التَّيَمُّنَ فِي طُهُورِهِ إِذَا تَطَهَّرَ وَفِي ‏ ‏تَرَجُّلِهِ ‏ ‏إِذَا تَرَجَّلَ وَفِي انْتِعَالِهِ إِذَا انْتَعَلَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9077ff19-e973-5281-88dc-4efe816c2486', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '396', '‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ التَّيَمُّنَ فِي شَأْنِهِ كُلِّهِ فِي نَعْلَيْهِ وَتَرَجُّلِهِ وَطُهُورِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1cc791ea-b2d9-52c5-a46c-45c0547637c8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '397', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ ‏ ‏وَابْنُ حُجْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اتَّقُوا ‏ ‏اللَّعَّانَيْنِ ‏ ‏قَالُوا وَمَا اللَّعَّانَانِ يَا رَسُولَ اللَّهِ قَالَ الَّذِي ‏ ‏يَتَخَلَّى ‏ ‏فِي طَرِيقِ النَّاسِ أَوْ فِي ظِلِّهِمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9c4f8883-e8f5-56d9-abec-82273deb4768', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '398', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏حَائِطًا ‏ ‏وَتَبِعَهُ ‏ ‏غُلَامٌ ‏ ‏مَعَهُ ‏ ‏مِيضَأَةٌ ‏ ‏هُوَ أَصْغَرُنَا فَوَضَعَهَا عِنْدَ سِدْرَةٍ فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَتَهُ فَخَرَجَ عَلَيْنَا وَقَدْ ‏ ‏اسْتَنْجَى ‏ ‏بِالْمَاءِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7666e379-7b06-593e-ba88-fda9da542f4a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '399', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَغُنْدَرٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُا ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ الْخَلَاءَ فَأَحْمِلُ أَنَا ‏ ‏وَغُلَامٌ ‏ ‏نَحْوِي إِدَاوَةً مِنْ مَاءٍ وَعَنَزَةً ‏ ‏فَيَسْتَنْجِي بِالْمَاءِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7a3c5b08-2e1e-5dd2-a7bc-6a8ee4c6afc3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '400', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِزُهَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ يَعْنِي ابْنَ عُلَيَّةَ ‏ ‏حَدَّثَنِي ‏ ‏رَوْحُ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَبَرَّزُ لِحَاجَتِهِ ‏ ‏فَآتِيهِ بِالْمَاءِ ‏ ‏فَيَتَغَسَّلُ بِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cbf0416b-be15-542a-951f-aa971251e2e0', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '401', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏وَاللَّفْظُ ‏ ‏لِيَحْيَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏قَالَ ‏ ‏بَالَ ‏ ‏جَرِيرٌ ‏ ‏ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقِيلَ تَفْعَلُ هَذَا فَقَالَ نَعَمْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ ثُمَّ تَوَضَّأَ ‏ ‏وَمَسَحَ عَلَى خُفَّيْهِ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏كَانَ يُعْجِبُهُمْ هَذَا الْحَدِيثُ لِأَنَّ إِسْلَامَ ‏ ‏جَرِيرٍ ‏ ‏كَانَ بَعْدَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏ ‏و حَدَّثَنَاه ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَلِيُّ بْنُ خَشْرَمٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏ح ‏ ‏و حَدَّثَنَاه ‏ ‏مُحَمَّدُ بْنُ أَبِي عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مِنْجَابُ بْنُ الْحَارِثِ التَّمِيمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ مُسْهِرٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏بِمَعْنَى حَدِيثِ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏غَيْرَ أَنَّ فِي حَدِيثِ ‏ ‏عِيسَى ‏ ‏وَسُفْيَانَ ‏ ‏قَالَ فَكَانَ أَصْحَابُ ‏ ‏عَبْدِ اللَّهِ ‏ ‏يُعْجِبُهُمْ هَذَا الْحَدِيثُ لِأَنَّ إِسْلَامَ ‏ ‏جَرِيرٍ ‏ ‏كَانَ بَعْدَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
