insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8cceb51a-6f38-59ab-ac48-c422a1839333', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '403', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو مُوسَى ‏ ‏يُشَدِّدُ فِي الْبَوْلِ وَيَبُولُ فِي قَارُورَةٍ وَيَقُولُ إِنَّ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانَ إِذَا أَصَابَ جِلْدَ أَحَدِهِمْ بَوْلٌ ‏ ‏قَرَضَهُ ‏ ‏بِالْمَقَارِيضِ ‏ ‏فَقَالَ ‏ ‏حُذَيْفَةُ ‏ ‏لَوَدِدْتُ أَنَّ صَاحِبَكُمْ لَا يُشَدِّدُ هَذَا التَّشْدِيدَ فَلَقَدْ رَأَيْتُنِي أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَتَمَاشَى ‏ ‏فَأَتَى سُبَاطَةً خَلْفَ حَائِطٍ فَقَامَ كَمَا يَقُومُ أَحَدُكُمْ فَبَالَ ‏ ‏فَانْتَبَذْتُ ‏ ‏مِنْهُ فَأَشَارَ إِلَيَّ فَجِئْتُ فَقُمْتُ عِنْدَ عَقِبِهِ حَتَّى فَرَغَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c9f4b39e-0a29-5d37-9701-29d521df1555', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '404', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحِ بْنِ الْمُهَاجِرِ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ خَرَجَ لِحَاجَتِهِ فَاتَّبَعَهُ ‏ ‏الْمُغِيرَةُ ‏ ‏بِإِدَاوَةٍ ‏ ‏فِيهَا مَاءٌ فَصَبَّ عَلَيْهِ حِينَ فَرَغَ مِنْ حَاجَتِهِ فَتَوَضَّأَ ‏ ‏وَمَسَحَ عَلَى الْخُفَّيْنِ ‏ ‏وَفِي رِوَايَةِ ‏ ‏ابْنِ رُمْحٍ ‏ ‏مَكَانَ حِينَ حَتَّى ‏ ‏و حَدَّثَنَاه ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى بْنَ سَعِيدٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَقَالَ فَغَسَلَ وَجْهَهُ وَيَدَيْهِ وَمَسَحَ بِرَأْسِهِ ثُمَّ مَسَحَ عَلَى الْخُفَّيْنِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dc58b564-8a10-584d-aaa2-3727db414246', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '405', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ إِذْ نَزَلَ فَقَضَى حَاجَتَهُ ثُمَّ جَاءَ فَصَبَبْتُ عَلَيْهِ مِنْ ‏ ‏إِدَاوَةٍ ‏ ‏كَانَتْ مَعِي فَتَوَضَّأَ ‏ ‏وَمَسَحَ عَلَى خُفَّيْهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('445e2c2c-2454-5697-bad9-8276b5a69350', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '406', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَقَالَ يَا ‏ ‏مُغِيرَةُ ‏ ‏خُذْ ‏ ‏الْإِدَاوَةَ ‏ ‏فَأَخَذْتُهَا ثُمَّ خَرَجْتُ مَعَهُ فَانْطَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ‏ ‏تَوَارَى ‏ ‏عَنِّي فَقَضَى حَاجَتَهُ ثُمَّ جَاءَ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏شَامِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ فَذَهَبَ يُخْرِجُ يَدَهُ مِنْ كُمِّهَا فَضَاقَتْ عَلَيْهِ فَأَخْرَجَ يَدَهُ مِنْ أَسْفَلِهَا فَصَبَبْتُ عَلَيْهِ ‏ ‏فَتَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ مَسَحَ عَلَى خُفَّيْهِ ثُمَّ صَلَّى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f8c8f2c1-d1a6-53aa-94bd-4a9345329ee7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '407', '‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَلِيُّ بْنُ خَشْرَمٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ يُونُسَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَقْضِيَ حَاجَتَهُ فَلَمَّا رَجَعَ تَلَقَّيْتُهُ ‏ ‏بِالْإِدَاوَةِ ‏ ‏فَصَبَبْتُ عَلَيْهِ فَغَسَلَ يَدَيْهِ ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ لِيَغْسِلَ ذِرَاعَيْهِ فَضَاقَتْ الْجُبَّةُ فَأَخْرَجَهُمَا مِنْ تَحْتِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَهُمَا وَمَسَحَ رَأْسَهُ ‏ ‏وَمَسَحَ عَلَى خُفَّيْهِ ثُمَّ صَلَّى بِنَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b6a0f454-6af0-5b3f-a490-936a3ab065dc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '408', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فِي مَسِيرٍ فَقَالَ لِي ‏ ‏أَمَعَكَ مَاءٌ قُلْتُ نَعَمْ فَنَزَلَ عَنْ رَاحِلَتِهِ فَمَشَى حَتَّى ‏ ‏تَوَارَى ‏ ‏فِي سَوَادِ اللَّيْلِ ثُمَّ جَاءَ فَأَفْرَغْتُ عَلَيْهِ مِنْ ‏ ‏الْإِدَاوَةِ ‏ ‏فَغَسَلَ وَجْهَهُ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏مِنْ صُوفٍ فَلَمْ يَسْتَطِعْ أَنْ يُخْرِجَ ذِرَاعَيْهِ مِنْهَا حَتَّى أَخْرَجَهُمَا مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ ذِرَاعَيْهِ وَمَسَحَ بِرَأْسِهِ ثُمَّ أَهْوَيْتُ لِأَنْزِعَ خُفَّيْهِ فَقَالَ دَعْهُمَا فَإِنِّي أَدْخَلْتُهُمَا طَاهِرَتَيْنِ وَمَسَحَ عَلَيْهِمَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('53ec0d52-7ae0-5dad-9847-25e1566ee944', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '409', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ وَضَّأَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقَالَ لَهُ فَقَالَ إِنِّي أَدْخَلْتُهُمَا طَاهِرَتَيْنِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('40b9966c-8ff1-579d-8aab-9b5109a9823b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '410', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ بَزِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ الْمُزَنِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏تَخَلَّفَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَخَلَّفْتُ مَعَهُ فَلَمَّا قَضَى حَاجَتَهُ قَالَ ‏ ‏أَمَعَكَ مَاءٌ فَأَتَيْتُهُ ‏ ‏بِمِطْهَرَةٍ ‏ ‏فَغَسَلَ كَفَّيْهِ وَوَجْهَهُ ثُمَّ ذَهَبَ ‏ ‏يَحْسِرُ ‏ ‏عَنْ ذِرَاعَيْهِ فَضَاقَ كُمُّ ‏ ‏الْجُبَّةِ ‏ ‏فَأَخْرَجَ يَدَهُ مِنْ تَحْتِ ‏ ‏الْجُبَّةِ ‏ ‏وَأَلْقَى ‏ ‏الْجُبَّةَ ‏ ‏عَلَى مَنْكِبَيْهِ وَغَسَلَ ذِرَاعَيْهِ وَمَسَحَ ‏ ‏بِنَاصِيَتِهِ ‏ ‏وَعَلَى الْعِمَامَةِ وَعَلَى خُفَّيْهِ ثُمَّ رَكِبَ وَرَكِبْتُ فَانْتَهَيْنَا إِلَى الْقَوْمِ وَقَدْ قَامُوا فِي الصَّلَاةِ ‏ ‏يُصَلِّي بِهِمْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏وَقَدْ رَكَعَ بِهِمْ رَكْعَةً فَلَمَّا أَحَسَّ بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَهَبَ يَتَأَخَّرُ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ فَصَلَّى بِهِمْ فَلَمَّا سَلَّمَ قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقُمْتُ فَرَكَعْنَا الرَّكْعَةَ الَّتِي سَبَقَتْنَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7178600b-7c9a-59ac-b52d-da20f787e074', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '411', '‏ ‏حَدَّثَنَا ‏ ‏أُمَيَّةُ بْنُ بِسْطَامَ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْخُفَّيْنِ وَمُقَدَّمِ رَأْسِهِ وَعَلَى عِمَامَتِهِ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e569da3e-4840-5c38-9267-fbde5a2ebd8c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '412', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏وَمُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏يَحْيَى الْقَطَّانِ ‏ ‏قَالَ ‏ ‏ابْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَكْرٌ ‏ ‏وَقَدْ ‏ ‏سَمِعْتَ مِنَ ‏ ‏ابْنِ الْمُغِيرَةِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَمَسَحَ ‏ ‏بِنَاصِيَتِهِ ‏ ‏وَعَلَى الْعِمَامَةِ وَعَلَى الْخُفَّيْنِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('344e0235-b1ec-5cb2-83b8-0cea205a097e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '413', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏عَنْ ‏ ‏بِلَالٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْخُفَّيْنِ ‏ ‏وَالْخِمَارِ ‏ ‏وَفِي حَدِيثِ ‏ ‏عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏حَدَّثَنِي ‏ ‏بِلَالٌ ‏ ‏و حَدَّثَنِيهِ ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ يَعْنِي ابْنَ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ وَقَالَ فِي الْحَدِيثِ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('efabc334-a53f-5565-b984-365e531e032d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '414', '‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ قَيْسٍ الْمُلَائِيِّ ‏ ‏عَنْ ‏ ‏الْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عَائِشَةَ ‏ ‏أَسْأَلُهَا عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَتْ عَلَيْكَ ‏ ‏بِابْنِ أَبِي طَالِبٍ ‏ ‏فَسَلْهُ فَإِنَّهُ كَانَ يُسَافِرُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْنَاهُ فَقَالَ جَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةَ أَيَّامٍ ‏ ‏وَلَيَالِيَهُنَّ لِلْمُسَافِرِ وَيَوْمًا وَلَيْلَةً لِلْمُقِيمِ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏سُفْيَانُ ‏ ‏إِذَا ذَكَرَ ‏ ‏عَمْرًا ‏ ‏أَثْنَى عَلَيْهِ ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّاءُ بْنُ عَدِيٍّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي أُنَيْسَةَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَتْ ائْتِ ‏ ‏عَلِيًّا ‏ ‏فَإِنَّهُ أَعْلَمُ بِذَلِكَ مِنِّي فَأَتَيْتُ ‏ ‏عَلِيًّا ‏ ‏فَذَكَرَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e4a1062d-4ce4-5d73-9e34-ab66ef842aad', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '415', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الصَّلَوَاتِ يَوْمَ الْفَتْحِ بِوُضُوءٍ وَاحِدٍ وَمَسَحَ عَلَى خُفَّيْهِ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏لَقَدْ صَنَعْتَ الْيَوْمَ شَيْئًا لَمْ تَكُنْ تَصْنَعُهُ قَالَ عَمْدًا صَنَعْتُهُ يَا ‏ ‏عُمَرُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c417ad53-3b33-57e6-b615-173822c8bb5d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '416', '‏ ‏و حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏وَحَامِدُ بْنُ عُمَرَ الْبَكْرَاوِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلَا ‏ ‏يَغْمِسْ ‏ ‏يَدَهُ فِي الْإِنَاءِ حَتَّى يَغْسِلَهَا ثَلَاثًا فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏وَأَبُو سَعِيدٍ الْأَشَجُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏وَأَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فِي حَدِيثِ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي حَدِيثِ ‏ ‏وَكِيعٍ ‏ ‏قَالَ يَرْفَعُهُ بِمِثْلِهِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِيهِ ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d7ddc638-e7ef-5fad-b73e-dfcc7d7aadd2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '417', '‏ ‏و حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ شَبِيبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ أَعْيَنَ ‏ ‏حَدَّثَنَا ‏ ‏مَعْقِلٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ ‏ ‏فَلْيُفْرِغْ ‏ ‏عَلَى يَدِهِ ثَلَاثَ مَرَّاتٍ قَبْلَ أَنْ يُدْخِلَ يَدَهُ فِي إِنَائِهِ فَإِنَّهُ لَا يَدْرِي فِيمَ بَاتَتْ يَدُهُ ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ يَعْنِي الْحِزَامِيَّ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏الْحُلْوَانِيُّ ‏ ‏وَابْنُ رَافِعٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَا ‏ ‏جَمِيعًا ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏زِيَادٌ ‏ ‏أَنَّ ‏ ‏ثَابِتًا ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زَيْدٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فِي رِوَايَتِهِمْ جَمِيعًا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَذَا الْحَدِيثِ كُلُّهُمْ يَقُولُ حَتَّى يَغْسِلَهَا وَلَمْ يَقُلْ وَاحِدٌ مِنْهُمْ ثَلَاثًا إِلَّا مَا قَدَّمْنَا مِنْ رِوَايَةِ ‏ ‏جَابِرٍ ‏ ‏وَابْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏وَعَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏وَأَبِي صَالِحٍ ‏ ‏وَأَبِي رَزِينٍ ‏ ‏فَإِنَّ فِي حَدِيثِهِمْ ذِكْرَ الثَّلَاثِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cb207578-430c-5ace-8489-c4b9442ae663', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '418', '‏ ‏و حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ حُجْرٍ السَّعْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏وَأَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ ‏ ‏فَلْيُرِقْهُ ‏ ‏ثُمَّ لِيَغْسِلْهُ سَبْعَ مِرَارٍ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ زَكَرِيَّاءَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ وَلَمْ يَقُلْ ‏ ‏فَلْيُرِقْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('82b721a7-405b-5b14-912b-cf0ee5092bc2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '419', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a874a6c1-cae5-5561-b26e-b0e1831de845', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '420', '‏ ‏و حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَهُورُ إِنَاءِ أَحَدِكُمْ إِذَا ‏ ‏وَلَغَ ‏ ‏فِيهِ الْكَلْبُ أَنْ يَغْسِلَهُ سَبْعَ مَرَّاتٍ أُولَاهُنَّ بِالتُّرَابِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5958edd3-da2b-5862-ba43-2e0eaa1557c1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '421', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏قَالَ هَذَا مَا حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَحَادِيثَ مِنْهَا ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَهُورُ إِنَاءِ أَحَدِكُمْ إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِيهِ أَنْ يَغْسِلَهُ سَبْعَ مَرَّاتٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5e31e876-3ab6-5586-a737-293fcca79800', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '422', '‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏سَمِعَ ‏ ‏مُطَرِّفَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ الْمُغَفَّلِ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ الْكِلَابِ ثُمَّ قَالَ مَا بَالُهُمْ وَبَالُ الْكِلَابِ ثُمَّ رَخَّصَ فِي كَلْبِ الصَّيْدِ وَكَلْبِ الْغَنَمِ وَقَالَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي الْإِنَاءِ فَاغْسِلُوهُ سَبْعَ مَرَّاتٍ ‏ ‏وَعَفِّرُوهُ ‏ ‏الثَّامِنَةَ فِي التُّرَابِ ‏ ‏و حَدَّثَنِيهِ ‏ ‏يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ الْحَارِثِ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏بِمِثْلِهِ ‏ ‏غَيْرَ أَنَّ فِي رِوَايَةِ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏مِنْ الزِّيَادَةِ وَرَخَّصَ فِي كَلْبِ الْغَنَمِ وَالصَّيْدِ وَالزَّرْعِ وَلَيْسَ ذَكَرَ الزَّرْعَ فِي الرِّوَايَةِ غَيْرُ ‏ ‏يَحْيَى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
