insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9568a7b4-975a-541a-a3b1-ecc93be25275', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '424', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏ثُمَّ يَغْتَسِلُ مِنْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4ddf89a3-5277-547b-b05b-ef8ec67c4d04', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '425', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏قَالَ هَذَا مَا حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَحَادِيثَ مِنْهَا ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَبُلْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏الَّذِي لَا يَجْرِي ثُمَّ تَغْتَسِلُ مِنْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c6d24b8-7b0e-5c4b-8d34-01e976701a98', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '426', '‏ ‏و حَدَّثَنَا ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏وَأَبُو الطَّاهِرِ ‏ ‏وَأَحْمَدُ بْنُ عِيسَى ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ وَهْبٍ ‏ ‏قَالَ ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ الْأَشَجِّ ‏ ‏أَنَّ ‏ ‏أَبَا السَّائِبِ ‏ ‏مَوْلَى ‏ ‏هِشَامِ بْنِ زُهْرَةَ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَغْتَسِلْ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏وَهُوَ جُنُبٌ ‏ ‏فَقَالَ ‏ ‏كَيْفَ يَفْعَلُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ يَتَنَاوَلُهُ تَنَاوُلًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('873ab8d4-bea8-5886-a5aa-ada75284e874', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '427', '‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ وَهُوَ ابْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ أَعْرَابِيًّا بَالَ فِي الْمَسْجِدِ فَقَامَ إِلَيْهِ بَعْضُ الْقَوْمِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهُ وَلَا ‏ ‏تُزْرِمُوهُ ‏ ‏قَالَ فَلَمَّا فَرَغَ دَعَا بِدَلْوٍ مِنْ مَاءٍ فَصَبَّهُ عَلَيْهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b0506772-8030-5f2e-ae71-fe4abfeb75b3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '428', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ الْأَنْصَارِيِّ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الدَّرَاوَرْدِيِّ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ الْمَدَنِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَذْكُرُ أَنَّ أَعْرَابِيًّا قَامَ إِلَى نَاحِيَةٍ فِي الْمَسْجِدِ فَبَالَ فِيهَا فَصَاحَ بِهِ النَّاسُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهُ فَلَمَّا فَرَغَ أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَنُوبٍ ‏ ‏فَصُبَّ عَلَى بَوْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('861cef3a-8ce2-5320-9464-11360e972d70', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '429', '‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ يُونُسَ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ أَبِي طَلْحَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏وَهُوَ عَمُّ ‏ ‏إِسْحَقَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ فِي الْمَسْجِدِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ جَاءَ أَعْرَابِيٌّ فَقَامَ يَبُولُ فِي الْمَسْجِدِ فَقَالَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَهْ ‏ ‏مَهْ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُزْرِمُوهُ ‏ ‏دَعُوهُ فَتَرَكُوهُ حَتَّى بَالَ ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَاهُ فَقَالَ لَهُ إِنَّ هَذِهِ الْمَسَاجِدَ لَا تَصْلُحُ لِشَيْءٍ مِنْ هَذَا الْبَوْلِ وَلَا الْقَذَرِ إِنَّمَا هِيَ لِذِكْرِ اللَّهِ عَزَّ وَجَلَّ وَالصَّلَاةِ وَقِرَاءَةِ الْقُرْآنِ أَوْ كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَمَرَ رَجُلًا مِنْ الْقَوْمِ فَجَاءَ بِدَلْوٍ مِنْ مَاءٍ ‏ ‏فَشَنَّهُ ‏ ‏عَلَيْهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('61cde793-d16c-5dde-97af-3191da1ce9e9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '430', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُؤْتَى بِالصِّبْيَانِ ‏ ‏فَيُبَرِّكُ ‏ ‏عَلَيْهِمْ ‏ ‏وَيُحَنِّكُهُمْ ‏ ‏فَأُتِيَ بِصَبِيٍّ فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ فَأَتْبَعَهُ بَوْلَهُ وَلَمْ يَغْسِلْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4a56fb2f-fca8-5eb9-8516-3be516c8040e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '431', '‏ ‏و حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِصَبِيٍّ يَرْضَعُ ‏ ‏فَبَالَ فِي ‏ ‏حَجْرِهِ ‏ ‏فَدَعَا بِمَاءٍ فَصَبَّهُ عَلَيْهِ ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏ابْنِ نُمَيْرٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d31ab926-c37d-5e80-9699-75be7460adfb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '432', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحِ بْنِ الْمُهَاجِرِ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏أَنَّهَا أَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنٍ لَهَا لَمْ يَأْكُلْ الطَّعَامَ فَوَضَعَتْهُ فِي ‏ ‏حَجْرِهِ ‏ ‏فَبَالَ قَالَ فَلَمْ يَزِدْ عَلَى أَنْ ‏ ‏نَضَحَ ‏ ‏بِالْمَاءِ ‏ ‏و حَدَّثَنَاه ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَقَالَ فَدَعَا بِمَاءٍ فَرَشَّهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92638e5c-b114-569e-bfde-bc2554f1ef14', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '433', '‏ ‏و حَدَّثَنِيهِ ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏أَنَّ ‏ ‏ابْنَ شِهَابٍ ‏ ‏أَخْبَرَهُ قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏أُمَّ قَيْسٍ بِنْتَ مِحْصَنٍ ‏ ‏وَكَانَتْ مِنْ الْمُهَاجِرَاتِ الْأُوَلِ اللَّاتِي بَايَعْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ أُخْتُ ‏ ‏عُكَّاشَةَ بْنِ مِحْصَنٍ ‏ ‏أَحَدُ ‏ ‏بَنِي أَسَدِ بْنِ خُزَيْمَةَ ‏ ‏قَالَ ‏ ‏أَخْبَرَتْنِي أَنَّهَا أَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنٍ لَهَا لَمْ يَبْلُغْ أَنْ يَأْكُلَ الطَّعَامَ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَخْبَرَتْنِي أَنَّ ابْنَهَا ذَاكَ ‏ ‏بَالَ فِي ‏ ‏حَجْرِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَاءٍ ‏ ‏فَنَضَحَهُ ‏ ‏عَلَى ثَوْبِهِ وَلَمْ يَغْسِلْهُ غَسْلًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da80bfaf-becd-573d-af2d-244f23465054', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '434', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏وَالْأَسْوَدِ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏نَزَلَ ‏ ‏بِعَائِشَةَ ‏ ‏فَأَصْبَحَ يَغْسِلُ ثَوْبَهُ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنَّمَا كَانَ يُجْزِئُكَ إِنْ رَأَيْتَهُ أَنْ تَغْسِلَ مَكَانَهُ فَإِنْ لَمْ تَرَ ‏ ‏نَضَحْتَ ‏ ‏حَوْلَهُ وَلَقَدْ رَأَيْتُنِي أَفْرُكُهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرْكًا فَيُصَلِّي فِيهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('273950d8-80d5-5ade-91c6-db9df24ad824', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '435', '‏ ‏و حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏وَهَمَّامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فِي الْمَنِيِّ قَالَتْ ‏ ‏كُنْتُ أَفْرُكُهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَرُوبَةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَهْدِيِّ بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏وَاصِلٍ الْأَحْدَبِ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏ابْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَمُغِيرَةَ ‏ ‏كُلُّ هَؤُلَاءِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فِي حَتِّ الْمَنِيِّ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏بِنَحْوِ حَدِيثِهِمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3e9caf8c-1420-5412-a546-acb93437bb03', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '436', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏عَنْ الْمَنِيِّ يُصِيبُ ثَوْبَ الرَّجُلِ أَيَغْسِلُهُ أَمْ يَغْسِلُ الثَّوْبَ ‏ ‏فَقَالَ أَخْبَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْسِلُ الْمَنِيَّ ثُمَّ يَخْرُجُ إِلَى الصَّلَاةِ فِي ذَلِكَ الثَّوْبِ وَأَنَا أَنْظُرُ إِلَى أَثَرِ الْغَسْلِ فِيهِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي ابْنَ زِيَادٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏وَابْنُ أَبِي زَائِدَةَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏أَمَّا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏فَحَدِيثُهُ كَمَا قَالَ ‏ ‏ابْنُ بِشْرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَغْسِلُ الْمَنِيَّ ‏ ‏وَأَمَّا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏وَعَبْدُ الْوَاحِدِ ‏ ‏فَفِي حَدِيثِهِمَا قَالَتْ كُنْتُ أَغْسِلُهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('645c8ce0-ec74-5303-9690-5602d41b6f97', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '437', '‏ ‏و حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ جَوَّاسٍ الْحَنَفِيُّ أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏شَبِيبِ بْنِ غَرْقَدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شِهَابٍ الْخَوْلَانِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ نَازِلًا عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَاحْتَلَمْتُ فِي ثَوْبَيَّ فَغَمَسْتُهُمَا فِي الْمَاءِ فَرَأَتْنِي جَارِيَةٌ ‏ ‏لِعَائِشَةَ ‏ ‏فَأَخْبَرَتْهَا فَبَعَثَتْ إِلَيَّ ‏ ‏عَائِشَةُ ‏ ‏فَقَالَتْ ‏ ‏مَا حَمَلَكَ عَلَى مَا صَنَعْتَ بِثَوْبَيْكَ قَالَ قُلْتُ رَأَيْتُ مَا يَرَى النَّائِمُ فِي مَنَامِهِ قَالَتْ هَلْ رَأَيْتَ فِيهِمَا شَيْئًا قُلْتُ لَا قَالَتْ فَلَوْ رَأَيْتَ شَيْئًا غَسَلْتَهُ لَقَدْ رَأَيْتُنِي وَإِنِّي لَأَحُكُّهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَابِسًا بِظُفُرِي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('52f40e0e-fbd7-5d31-8549-37762076cab2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '438', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ امْرَأَةٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِحْدَانَا يُصِيبُ ثَوْبَهَا مِنْ دَمِ الْحَيْضَةِ كَيْفَ تَصْنَعُ بِهِ قَالَ ‏ ‏تَحُتُّهُ ثُمَّ تَقْرُصُهُ بِالْمَاءِ ثُمَّ تَنْضَحُهُ ثُمَّ تُصَلِّي فِيهِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ سَالِمٍ ‏ ‏وَمَالِكُ بْنُ أَنَسٍ ‏ ‏وَعَمْرُو بْنُ الْحَارِثِ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4ec8169c-f2f6-54fd-8273-8d8b1ebc5550', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '439', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْأَشَجُّ ‏ ‏وَأَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَبْرَيْنِ فَقَالَ ‏ ‏أَمَا إِنَّهُمَا لَيُعَذَّبَانِ وَمَا يُعَذَّبَانِ فِي كَبِيرٍ أَمَّا أَحَدُهُمَا فَكَانَ يَمْشِي بِالنَّمِيمَةِ وَأَمَّا الْآخَرُ فَكَانَ لَا يَسْتَتِرُ مِنْ بَوْلِهِ قَالَ فَدَعَا بِعَسِيبٍ رَطْبٍ فَشَقَّهُ بِاثْنَيْنِ ثُمَّ غَرَسَ عَلَى هَذَا وَاحِدًا وَعَلَى هَذَا وَاحِدًا ثُمَّ قَالَ لَعَلَّهُ أَنْ يُخَفَّفُ عَنْهُمَا مَا لَمْ يَيْبَسَا ‏ ‏حَدَّثَنِيهِ ‏ ‏أَحْمَدُ بْنُ يُوسُفَ الْأَزْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏غَيْرَ أَنَّهُ قَالَ وَكَانَ الْآخَرُ لَا يَسْتَنْزِهُ عَنْ الْبَوْلِ أَوْ مِنْ الْبَوْلِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a6929cca-e213-56c5-806f-170deb3c45fc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '440', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ إِحْدَانَا إِذَا كَانَتْ حَائِضًا أَمَرَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَأْتَزِرُ ‏ ‏بِإِزَارٍ ‏ ‏ثُمَّ ‏ ‏يُبَاشِرُهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8c19e9d5-bd49-54d9-b3cf-0901ef1408a8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '441', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ حُجْرٍ السَّعْدِيُّ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ إِحْدَانَا إِذَا كَانَتْ حَائِضًا ‏ ‏أَمَرَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تَأْتَزِرَ ‏ ‏فِي فَوْرِ حَيْضَتِهَا ثُمَّ ‏ ‏يُبَاشِرُهَا ‏ ‏قَالَتْ وَأَيُّكُمْ يَمْلِكُ ‏ ‏إِرْبَهُ ‏ ‏كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْلِكُ ‏ ‏إِرْبَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('45bf2e6b-e909-5910-8819-f1c7d1c6b25e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '442', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ ‏ ‏نِسَاءَهُ فَوْقَ ‏ ‏الْإِزَارِ ‏ ‏وَهُنَّ حُيَّضٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4f41b255-1f27-5ee3-a10f-ea1f7f94c398', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '443', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏مَخْرَمَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏وَأَحْمَدُ بْنُ عِيسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏مَخْرَمَةُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَضْطَجِعُ مَعِي وَأَنَا حَائِضٌ وَبَيْنِي وَبَيْنَهُ ثَوْبٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('59407f19-4010-5aa0-a538-b443b71c471d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '444', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ بِنْتَ أُمِّ سَلَمَةَ ‏ ‏حَدَّثَتْهُ أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏حَدَّثَتْهَا قَالَتْ ‏ ‏بَيْنَمَا أَنَا مُضْطَجِعَةٌ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْخَمِيلَةِ إِذْ حِضْتُ فَانْسَلَلْتُ فَأَخَذْتُ ثِيَابَ حِيضَتِي فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَفِسْتِ ‏ ‏قُلْتُ نَعَمْ فَدَعَانِي فَاضْطَجَعْتُ مَعَهُ فِي ‏ ‏الْخَمِيلَةِ ‏ ‏قَالَتْ وَكَانَتْ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلَانِ فِي الْإِنَاءِ الْوَاحِدِ مِنْ الْجَنَابَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5fa648b7-2a60-52c4-b74c-f20f41aa7e3e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '445', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اعْتَكَفَ يُدْنِي إِلَيَّ رَأْسَهُ ‏ ‏فَأُرَجِّلُهُ ‏ ‏وَكَانَ لَا يَدْخُلُ الْبَيْتَ إِلَّا لِحَاجَةِ الْإِنْسَانِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('950ec6be-2b5e-58e3-957e-2c0a876e8712', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '446', '‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏وَعَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏إِنْ كُنْتُ لَأَدْخُلُ الْبَيْتَ لِلْحَاجَةِ وَالْمَرِيضُ فِيهِ فَمَا أَسْأَلُ عَنْهُ إِلَّا وَأَنَا مَارَّةٌ وَإِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُدْخِلُ عَلَيَّ رَأْسَهُ وَهُوَ فِي الْمَسْجِدِ فَأُرَجِّلُهُ وَكَانَ لَا يَدْخُلُ الْبَيْتَ إِلَّا لِحَاجَةٍ إِذَا كَانَ مُعْتَكِفًا ‏ ‏و قَالَ ‏ ‏ابْنُ رُمْحٍ ‏ ‏إِذَا كَانُوا مُعْتَكِفِينَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('51cd773e-8071-5c95-974d-8e5cf1ba9902', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '447', '‏ ‏و حَدَّثَنِي ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخْرِجُ إِلَيَّ رَأْسَهُ مِنْ الْمَسْجِدِ وَهُوَ مُجَاوِرٌ فَأَغْسِلُهُ وَأَنَا حَائِضٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9d587976-ce50-526c-8e13-3d894ef14ea1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '448', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُدْنِي إِلَيَّ رَأْسَهُ وَأَنَا فِي حُجْرَتِي فَأُرَجِّلُ رَأْسَهُ وَأَنَا حَائِضٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2b7687c1-7b1d-5635-a190-c11af859af4d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '449', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْسِلُ رَأْسَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا حَائِضٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f84175e3-47fb-5255-b3f6-f6023b24aaf8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '450', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ قَالَتْ فَقُلْتُ إِنِّي حَائِضٌ فَقَالَ إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c14330d3-d011-55ae-8e6a-f0b0e3f4b734', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '451', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏وَابْنِ أَبِي غَنِيَّةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُنَاوِلَهُ ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ فَقُلْتُ إِنِّي حَائِضٌ فَقَالَ ‏ ‏تَنَاوَلِيهَا فَإِنَّ الْحَيْضَةَ لَيْسَتْ فِي يَدِكِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('303be7c1-9d19-5a90-b8ea-e1360a733b62', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '452', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏وَمُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏نَاوِلِينِي الثَّوْبَ فَقَالَتْ إِنِّي حَائِضٌ فَقَالَ إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ فَنَاوَلَتْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d6a7e6b0-0c77-5455-96c7-aabd2f0732df', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '453', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏وَسُفْيَانَ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَشْرَبُ وَأَنَا حَائِضٌ ثُمَّ أُنَاوِلُهُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَضَعُ فَاهُ عَلَى مَوْضِعِ ‏ ‏فِيَّ فَيَشْرَبُ ‏ ‏وَأَتَعَرَّقُ ‏ ‏الْعَرْقَ ‏ ‏وَأَنَا حَائِضٌ ثُمَّ أُنَاوِلُهُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَضَعُ فَاهُ عَلَى مَوْضِعِ ‏ ‏فِيَّ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏زُهَيْرٌ ‏ ‏فَيَشْرَبُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('360abc85-93a1-5044-ae36-73aa2eea4e18', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '454', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ عَبْدِ الرَّحْمَنِ الْمَكِّيُّ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَّكِئُ فِي ‏ ‏حِجْرِي ‏ ‏وَأَنَا حَائِضٌ فَيَقْرَأُ الْقُرْآنَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e719b368-7105-5061-b8f1-8de351cd89d2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '455', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏الْيَهُودَ ‏ ‏كَانُوا إِذَا حَاضَتْ الْمَرْأَةُ فِيهِمْ لَمْ يُؤَاكِلُوهَا وَلَمْ يُجَامِعُوهُنَّ فِي الْبُيُوتِ فَسَأَلَ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏وَيَسْأَلُونَكَ عَنْ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ ‏} ‏إِلَى آخِرِ الْآيَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اصْنَعُوا كُلَّ شَيْءٍ إِلَّا النِّكَاحَ فَبَلَغَ ذَلِكَ ‏ ‏الْيَهُودَ ‏ ‏فَقَالُوا مَا يُرِيدُ هَذَا الرَّجُلُ أَنْ يَدَعَ مِنْ أَمْرِنَا شَيْئًا إِلَّا خَالَفَنَا فِيهِ فَجَاءَ ‏ ‏أُسَيْدُ بْنُ حُضَيْرٍ ‏ ‏وَعَبَّادُ بْنُ بِشْرٍ ‏ ‏فَقَالَا يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏الْيَهُودَ ‏ ‏تَقُولُ كَذَا وَكَذَا فَلَا نُجَامِعُهُنَّ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ظَنَنَّا أَنْ قَدْ ‏ ‏وَجَدَ ‏ ‏عَلَيْهِمَا فَخَرَجَا فَاسْتَقْبَلَهُمَا هَدِيَّةٌ مِنْ لَبَنٍ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْسَلَ فِي آثَارِهِمَا فَسَقَاهُمَا فَعَرَفَا أَنْ لَمْ ‏ ‏يَجِدْ ‏ ‏عَلَيْهِمَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f7c755bf-9545-58ee-b8dd-4f0ef44c8318', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '456', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏وَهُشَيْمٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُنْذِرِ بْنِ يَعْلَى وَيُكْنَى أَبَا يَعْلَى ‏ ‏عَنْ ‏ ‏ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏كُنْتُ رَجُلًا مَذَّاءً وَكُنْتُ ‏ ‏أَسْتَحْيِي أَنْ أَسْأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِمَكَانِ ابْنَتِهِ فَأَمَرْتُ ‏ ‏الْمِقْدَادَ بْنَ الْأَسْوَدِ ‏ ‏فَسَأَلَهُ فَقَالَ ‏ ‏يَغْسِلُ ذَكَرَهُ وَيَتَوَضَّأُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b568b07b-e80e-5902-98ef-2fe2f383557f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '457', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُنْذِرًا ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّهُ قَالَ ‏ ‏اسْتَحْيَيْتُ أَنْ أَسْأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمَذْيِ ‏ ‏مِنْ أَجْلِ ‏ ‏فَاطِمَةَ ‏ ‏فَأَمَرْتُ ‏ ‏الْمِقْدَادَ ‏ ‏فَسَأَلَهُ فَقَالَ ‏ ‏مِنْهُ الْوُضُوءُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3e1aa9c2-2709-52a9-904c-4ba01737bd20', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '458', '‏ ‏و حَدَّثَنِي ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏وَأَحْمَدُ بْنُ عِيسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏مَخْرَمَةُ بْنُ بُكَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏أَرْسَلْنَا ‏ ‏الْمِقْدَادَ بْنَ الْأَسْوَدِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ ‏ ‏الْمَذْيِ ‏ ‏يَخْرُجُ مِنْ الْإِنْسَانِ كَيْفَ يَفْعَلُ بِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأْ ‏ ‏وَانْضَحْ ‏ ‏فَرْجَكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('06991dc3-b408-5dd3-b0f0-7ed805c9e07c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '459', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ مِنْ اللَّيْلِ فَقَضَى حَاجَتَهُ ثُمَّ غَسَلَ وَجْهَهُ وَيَدَيْهِ ثُمَّ نَامَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b738a185-a7da-5bec-8980-23400752589c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '460', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏وَمُحَمَّدُ بْنُ رُمْحٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَرَادَ أَنْ يَنَامَ وَهُوَ جُنُبٌ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ قَبْلَ أَنْ يَنَامَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b1f13620-8fa5-5762-b8c6-f5db8c7421f3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '461', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏وَوَكِيعٌ ‏ ‏وَغُنْدَرٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏كَانَ جُنُبًا فَأَرَادَ أَنْ يَأْكُلَ أَوْ يَنَامَ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُثَنَّى ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏سَمِعْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏يُحَدِّثُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2a84d684-2036-52a1-b60f-e6480ee1d149', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '462', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَحْيَى وَهُوَ ابْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏وَاللَّفْظُ لَهُمَا ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَيَرْقُدُ أَحَدُنَا وَهُوَ جُنُبٌ قَالَ ‏ ‏نَعَمْ إِذَا تَوَضَّأَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e1fef238-600d-576b-ba2e-39fe7bc3d6c7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '463', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏اسْتَفْتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏هَلْ يَنَامُ أَحَدُنَا وَهُوَ جُنُبٌ قَالَ نَعَمْ لِيَتَوَضَّأْ ثُمَّ لِيَنَمْ حَتَّى يَغْتَسِلَ إِذَا شَاءَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5bd59f0f-b238-5f83-825c-0b6d93f4485e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '464', '‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏ذَكَرَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ تُصِيبُهُ جَنَابَةٌ مِنْ اللَّيْلِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأْ وَاغْسِلْ ذَكَرَكَ ثُمَّ نَمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('62c6c70e-c19a-5165-91db-0d170d093c39', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '465', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ وِتْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ قُلْتُ كَيْفَ كَانَ يَصْنَعُ فِي الْجَنَابَةِ أَكَانَ يَغْتَسِلُ قَبْلَ أَنْ يَنَامَ أَمْ يَنَامُ قَبْلَ أَنْ يَغْتَسِلَ قَالَتْ كُلُّ ذَلِكَ قَدْ كَانَ يَفْعَلُ ‏ ‏رُبَّمَا اغْتَسَلَ فَنَامَ وَرُبَّمَا تَوَضَّأَ فَنَامَ قُلْتُ الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً ‏ ‏و حَدَّثَنِيهِ ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏ح ‏ ‏و حَدَّثَنِيهِ ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7e36ee82-184e-57f2-9b38-3f1c94a523df', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '466', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ أَهْلَهُ ثُمَّ أَرَادَ أَنْ يَعُودَ فَلْيَتَوَضَّأْ ‏ ‏زَادَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فِي حَدِيثِهِ بَيْنَهُمَا وُضُوءًا وَقَالَ ثُمَّ أَرَادَ أَنْ يُعَاوِدَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0ed60411-51d2-575b-895c-d61ac2ece038', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '467', '‏ ‏و حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ أَحْمَدَ بْنِ أَبِي شُعَيْبٍ الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مِسْكِينٌ يَعْنِي ابْنَ بُكَيْرٍ الْحَذَّاءَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَطُوفُ عَلَى نِسَائِهِ بِغُسْلٍ وَاحِدٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aaac1961-ade5-5539-a198-4b038d175f83', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '468', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ يُونُسَ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏قَالَ قَالَ ‏ ‏إِسْحَقُ بْنُ أَبِي طَلْحَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَاءَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏وَهِيَ جَدَّةُ ‏ ‏إِسْحَقَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ لَهُ ‏ ‏وَعَائِشَةُ ‏ ‏عِنْدَهُ يَا رَسُولَ اللَّهِ الْمَرْأَةُ ‏ ‏تَرَى مَا يَرَى الرَّجُلُ فِي الْمَنَامِ فَتَرَى مِنْ نَفْسِهَا مَا يَرَى الرَّجُلُ مِنْ نَفْسِهِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏فَضَحْتِ النِّسَاءَ تَرِبَتْ يَمِينُكِ فَقَالَ ‏ ‏لِعَائِشَةَ ‏ ‏بَلْ أَنْتِ فَتَرِبَتْ يَمِينُكِ نَعَمْ فَلْتَغْتَسِلْ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏إِذَا رَأَتْ ذَاكِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8617634d-0871-57b4-8eea-bee57d883653', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '469', '‏ ‏حَدَّثَنَا ‏ ‏عَبَّاسُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُمْ أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏حَدَّثَتْ ‏ ‏أَنَّهَا سَأَلَتْ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمَرْأَةِ ‏ ‏تَرَى فِي مَنَامِهَا مَا يَرَى الرَّجُلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَتْ ذَلِكِ الْمَرْأَةُ فَلْتَغْتَسِلْ فَقَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏وَاسْتَحْيَيْتُ مِنْ ذَلِكَ قَالَتْ وَهَلْ يَكُونُ هَذَا فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ فَمِنْ أَيْنَ يَكُونُ الشَّبَهُ إِنَّ مَاءَ الرَّجُلِ غَلِيظٌ أَبْيَضُ وَمَاءَ الْمَرْأَةِ رَقِيقٌ أَصْفَرُ فَمِنْ أَيِّهِمَا عَلَا أَوْ سَبَقَ يَكُونُ مِنْهُ الشَّبَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('931d683f-9c11-532f-9547-083d0ca64deb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '470', '‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ رُشَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَالِكٍ الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏سَأَلَتْ امْرَأَةٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمَرْأَةِ ‏ ‏تَرَى فِي مَنَامِهَا مَا يَرَى الرَّجُلُ فِي مَنَامِهِ فَقَالَ ‏ ‏إِذَا كَانَ مِنْهَا مَا يَكُونُ مِنْ الرَّجُلِ فَلْتَغْتَسِلْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ea8036e7-a3b2-5de5-b001-27c2cc405fbe', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '471', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏أَمُّ سُلَيْمٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ فَهَلْ عَلَى الْمَرْأَةِ مِنْ غُسْلٍ إِذَا احْتَلَمَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ إِذَا رَأَتْ الْمَاءَ فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏يَا رَسُولَ اللَّهِ وَتَحْتَلِمُ الْمَرْأَةُ فَقَالَ تَرِبَتْ يَدَاكِ فَبِمَ يُشْبِهُهَا وَلَدُهَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَ مَعْنَاهُ وَزَادَ قَالَتْ قُلْتُ فَضَحْتِ النِّسَاءَ ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ شُعَيْبِ بْنِ اللَّيْثِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏أُمَّ بَنِي ‏ ‏أَبِي طَلْحَةَ ‏ ‏دَخَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَعْنَى حَدِيثِ ‏ ‏هِشَامٍ ‏ ‏غَيْرَ أَنَّ فِيهِ قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ لَهَا أُفٍّ لَكِ أَتَرَى الْمَرْأَةُ ذَلِكِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e9d28e10-00f6-5199-b904-2609c66cd135', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '472', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى الرَّازِيُّ ‏ ‏وَسَهْلُ بْنُ عُثْمَانَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي كُرَيْبٍ ‏ ‏قَالَ ‏ ‏سَهْلٌ ‏ ‏حَدَّثَنَا ‏ ‏و قَالَ ‏ ‏الْآخَرَانِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏مُسَافِعِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً قَالَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَغْتَسِلُ الْمَرْأَةُ إِذَا احْتَلَمَتْ وَأَبْصَرَتْ الْمَاءَ فَقَالَ نَعَمْ فَقَالَتْ لَهَا ‏ ‏عَائِشَةُ ‏ ‏تَرِبَتْ يَدَاكِ ‏ ‏وَأُلَّتْ ‏ ‏قَالَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعِيهَا وَهَلْ يَكُونُ الشَّبَهُ إِلَّا مِنْ قِبَلِ ذَلِكِ إِذَا عَلَا مَاؤُهَا مَاءَ الرَّجُلِ أَشْبَهَ الْوَلَدُ أَخْوَالَهُ وَإِذَا عَلَا مَاءُ الرَّجُلِ مَاءَهَا أَشْبَهَ أَعْمَامَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('911d4c8e-bcf6-503a-9603-af594d9d5400', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '473', '‏ ‏حَدَّثَنِي ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو تَوْبَةَ وَهُوَ الرَّبِيعُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ يَعْنِي ابْنَ سَلَّامٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏يَعْنِي أَخَاهُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَّامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو أَسْمَاءَ الرَّحَبِيُّ ‏ ‏أَنَّ ‏ ‏ثَوْبَانَ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏كُنْتُ قَائِمًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏حِبْرٌ ‏ ‏مِنْ ‏ ‏أَحْبَارِ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ السَّلَامُ عَلَيْكَ يَا ‏ ‏مُحَمَّدُ ‏ ‏فَدَفَعْتُهُ دَفْعَةً كَادَ يُصْرَعُ مِنْهَا فَقَالَ لِمَ تَدْفَعُنِي فَقُلْتُ أَلَا تَقُولُ يَا رَسُولَ اللَّهِ فَقَالَ الْيَهُودِيُّ إِنَّمَا نَدْعُوهُ بِاسْمِهِ الَّذِي سَمَّاهُ بِهِ أَهْلُهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اسْمِي ‏ ‏مُحَمَّدٌ ‏ ‏الَّذِي سَمَّانِي بِهِ أَهْلِي فَقَالَ الْيَهُودِيُّ جِئْتُ أَسْأَلُكَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيَنْفَعُكَ شَيْءٌ إِنْ حَدَّثْتُكَ قَالَ أَسْمَعُ بِأُذُنَيَّ ‏ ‏فَنَكَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعُودٍ مَعَهُ فَقَالَ سَلْ فَقَالَ الْيَهُودِيُّ أَيْنَ يَكُونُ النَّاسُ ‏ { ‏يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَوَاتُ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمْ فِي الظُّلْمَةِ دُونَ ‏ ‏الْجِسْرِ ‏ ‏قَالَ فَمَنْ أَوَّلُ النَّاسِ ‏ ‏إِجَازَةً ‏ ‏قَالَ فُقَرَاءُ ‏ ‏الْمُهَاجِرِينَ ‏ ‏قَالَ الْيَهُودِيُّ فَمَا ‏ ‏تُحْفَتُهُمْ ‏ ‏حِينَ يَدْخُلُونَ الْجَنَّةَ قَالَ زِيَادَةُ كَبِدِ ‏ ‏النُّونِ ‏ ‏قَالَ فَمَا غِذَاؤُهُمْ عَلَى ‏ ‏إِثْرِهَا ‏ ‏قَالَ يُنْحَرُ لَهُمْ ثَوْرُ الْجَنَّةِ الَّذِي كَانَ يَأْكُلُ مِنْ أَطْرَافِهَا قَالَ فَمَا شَرَابُهُمْ عَلَيْهِ قَالَ مِنْ عَيْنٍ فِيهَا تُسَمَّى سَلْسَبِيلًا قَالَ صَدَقْتَ قَالَ وَجِئْتُ أَسْأَلُكَ عَنْ شَيْءٍ لَا يَعْلَمُهُ أَحَدٌ مِنْ أَهْلِ الْأَرْضِ إِلَّا نَبِيٌّ أَوْ رَجُلٌ أَوْ رَجُلَانِ قَالَ يَنْفَعُكَ إِنْ حَدَّثْتُكَ قَالَ أَسْمَعُ بِأُذُنَيَّ قَالَ جِئْتُ أَسْأَلُكَ عَنْ الْوَلَدِ قَالَ مَاءُ الرَّجُلِ أَبْيَضُ وَمَاءُ الْمَرْأَةِ أَصْفَرُ فَإِذَا اجْتَمَعَا فَعَلَا مَنِيُّ الرَّجُلِ مَنِيَّ الْمَرْأَةِ أَذْكَرَا بِإِذْنِ اللَّهِ وَإِذَا عَلَا مَنِيُّ الْمَرْأَةِ مَنِيَّ الرَّجُلِ آنَثَا بِإِذْنِ اللَّهِ قَالَ الْيَهُودِيُّ لَقَدْ صَدَقْتَ وَإِنَّكَ لَنَبِيٌّ ثُمَّ انْصَرَفَ فَذَهَبَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ سَأَلَنِي هَذَا عَنْ الَّذِي سَأَلَنِي عَنْهُ وَمَا لِي عِلْمٌ بِشَيْءٍ مِنْهُ حَتَّى ‏ ‏أَتَانِيَ اللَّهُ بِهِ ‏ ‏و حَدَّثَنِيهِ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ الدَّارِمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ سَلَّامٍ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏بِمِثْلِهِ غَيْرَ أَنَّهُ قَالَ كُنْتُ قَاعِدًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ زَائِدَةُ كَبِدِ ‏ ‏النُّونِ ‏ ‏وَقَالَ أَذْكَرَ وَآنَثَ وَلَمْ يَقُلْ أَذْكَرَا وَآنَثَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4be0ff74-09c7-59f9-b2e4-11a1775e2a88', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '474', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اغْتَسَلَ مِنْ الْجَنَابَةِ يَبْدَأُ فَيَغْسِلُ يَدَيْهِ ثُمَّ يُفْرِغُ بِيَمِينِهِ عَلَى شِمَالِهِ فَيَغْسِلُ فَرْجَهُ ثُمَّ يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يَأْخُذُ الْمَاءَ فَيُدْخِلُ أَصَابِعَهُ فِي ‏ ‏أُصُولِ ‏ ‏الشَّعْرِ حَتَّى إِذَا رَأَى أَنْ قَدْ ‏ ‏اسْتَبْرَأَ ‏ ‏حَفَنَ ‏ ‏عَلَى رَأْسِهِ ثَلَاثَ ‏ ‏حَفَنَاتٍ ‏ ‏ثُمَّ ‏ ‏أَفَاضَ ‏ ‏عَلَى سَائِرِ جَسَدِهِ ثُمَّ غَسَلَ رِجْلَيْهِ ‏ ‏و حَدَّثَنَاه ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏فِي هَذَا الْإِسْنَادِ وَلَيْسَ فِي حَدِيثِهِمْ غَسْلُ الرِّجْلَيْنِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اغْتَسَلَ مِنْ الْجَنَابَةِ فَبَدَأَ فَغَسَلَ كَفَّيْهِ ثَلَاثًا ثُمَّ ذَكَرَ نَحْوَ حَدِيثِ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏وَلَمْ يَذْكُرْ غَسْلَ الرِّجْلَيْنِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c7a89662-2cf6-5b7e-bd11-b022c2ebde76', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '475', '‏ ‏و حَدَّثَنَاه ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا ‏ ‏اغْتَسَلَ مِنْ الْجَنَابَةِ بَدَأَ فَغَسَلَ يَدَيْهِ قَبْلَ أَنْ يُدْخِلَ يَدَهُ فِي الْإِنَاءِ ثُمَّ تَوَضَّأَ مِثْلَ وُضُوئِهِ لِلصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2703d206-ca5e-575f-b68e-c901214c729b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '476', '‏ ‏و حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ حُجْرٍ السَّعْدِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏خَالَتِي ‏ ‏مَيْمُونَةُ ‏ ‏قَالَتْ ‏ ‏أَدْنَيْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُسْلَهُ مِنْ الْجَنَابَةِ ‏ ‏فَغَسَلَ كَفَّيْهِ مَرَّتَيْنِ أَوْ ثَلَاثًا ثُمَّ أَدْخَلَ يَدَهُ فِي الْإِنَاءِ ثُمَّ أَفْرَغَ بِهِ عَلَى فَرْجِهِ وَغَسَلَهُ بِشِمَالِهِ ثُمَّ ضَرَبَ بِشِمَالِهِ الْأَرْضَ فَدَلَكَهَا دَلْكًا شَدِيدًا ثُمَّ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ أَفْرَغَ عَلَى رَأْسِهِ ثَلَاثَ حَفَنَاتٍ مِلْءَ كَفِّهِ ثُمَّ غَسَلَ سَائِرَ جَسَدِهِ ثُمَّ تَنَحَّى عَنْ مَقَامِهِ ذَلِكَ فَغَسَلَ رِجْلَيْهِ ثُمَّ أَتَيْتُهُ بِالْمِنْدِيلِ فَرَدَّهُ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَالْأَشَجُّ ‏ ‏وَإِسْحَقُ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏وَكِيعٍ ‏ ‏ح ‏ ‏و حَدَّثَنَاه ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَلَيْسَ فِي حَدِيثِهِمَا إِفْرَاغُ ثَلَاثِ حَفَنَاتٍ عَلَى الرَّأْسِ ‏ ‏وَفِي حَدِيثِ ‏ ‏وَكِيعٍ ‏ ‏وَصْفُ الْوُضُوءِ كُلِّهِ يَذْكُرُ الْمَضْمَضَةَ ‏ ‏وَالِاسْتِنْشَاقَ فِيهِ ‏ ‏وَلَيْسَ فِي حَدِيثِ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏ذِكْرُ الْمِنْدِيلِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a3803e18-a31a-5e43-b9a4-8298e780c23a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '477', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِمِنْدِيلٍ فَلَمْ يَمَسَّهُ وَجَعَلَ يَقُولُ بِالْمَاءِ هَكَذَا ‏ ‏يَعْنِي يَنْفُضُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('58589ccd-325a-5eb6-b9a6-4c424a0103ef', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '478', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى الْعَنَزِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اغْتَسَلَ مِنْ الْجَنَابَةِ دَعَا بِشَيْءٍ نَحْوَ الْحِلَابِ فَأَخَذَ بِكَفِّهِ بَدَأَ بِشِقِّ رَأْسِهِ الْأَيْمَنِ ثُمَّ الْأَيْسَرِ ثُمَّ أَخَذَ بِكَفَّيْهِ فَقَالَ بِهِمَا عَلَى رَأْسِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c04d8a95-c514-5f49-8104-77ad12f10eb9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '479', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ مِنْ إِنَاءٍ هُوَ ‏ ‏الْفَرَقُ ‏ ‏مِنْ الْجَنَابَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a511394c-cd2b-5221-a87d-9fc0734b654b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '480', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ رُمْحٍ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ فِي الْقَدَحِ ‏ ‏وَهُوَ الْفَرَقُ ‏ ‏وَكُنْتُ أَغْتَسِلُ أَنَا وَهُوَ فِي الْإِنَاءِ الْوَاحِدِ ‏ ‏وَفِي حَدِيثِ ‏ ‏سُفْيَانَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَالْفَرَقُ ثَلَاثَةُ ‏ ‏آصُعٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7a68f3d1-7bab-5217-aafc-756f313c0d2c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '481', '‏ ‏و حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏أَنَا وَأَخُوهَا مِنْ الرَّضَاعَةِ فَسَأَلَهَا عَنْ غُسْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ ‏ ‏فَدَعَتْ بِإِنَاءٍ قَدْرِ الصَّاعِ فَاغْتَسَلَتْ وَبَيْنَنَا وَبَيْنَهَا سِتْرٌ وَأَفْرَغَتْ عَلَى رَأْسِهَا ثَلَاثًا قَالَ وَكَانَ أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْخُذْنَ مِنْ رُءُوسِهِنَّ حَتَّى تَكُونَ ‏ ‏كَالْوَفْرَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ad4cfd1e-0a61-551b-bddd-5e8d40a01015', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '482', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏مَخْرَمَةُ بْنُ بُكَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اغْتَسَلَ بَدَأَ بِيَمِينِهِ فَصَبَّ عَلَيْهَا مِنْ الْمَاءِ فَغَسَلَهَا ثُمَّ صَبَّ الْمَاءَ عَلَى ‏ ‏الْأَذَى ‏ ‏الَّذِي بِهِ بِيَمِينِهِ وَغَسَلَ عَنْهُ بِشِمَالِهِ حَتَّى إِذَا فَرَغَ مِنْ ذَلِكَ صَبَّ عَلَى رَأْسِهِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ وَنَحْنُ جُنُبَانِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0cd4e447-929a-5020-83ba-51225ec02c23', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '483', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عِرَاكٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏وَكَانَتْ تَحْتَ ‏ ‏الْمُنْذِرِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهَا أَنَّهَا كَانَتْ ‏ ‏تَغْتَسِلُ هِيَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِنَاءٍ وَاحِدٍ يَسَعُ ثَلَاثَةَ ‏ ‏أَمْدَادٍ ‏ ‏أَوْ قَرِيبًا مِنْ ذَلِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e8c0f2ee-64b0-5243-84cc-68b67ee43816', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '484', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ بْنِ قَعْنَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَفْلَحُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ تَخْتَلِفُ أَيْدِينَا فِيهِ مِنْ الْجَنَابَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a2e50974-62d7-53bc-b2f6-e76c6d5e30cf', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '485', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ بَيْنِي وَبَيْنَهُ وَاحِدٍ فَيُبَادِرُنِي حَتَّى أَقُولَ دَعْ لِي دَعْ لِي قَالَتْ وَهُمَا جُنُبَانِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c64a167d-549b-5ef2-97f5-8a444e659b82', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '486', '‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏مَيْمُونَةُ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏تَغْتَسِلُ هِيَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِنَاءٍ وَاحِدٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('27057a53-90ac-56ba-a197-be112cb63d09', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '487', '‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَمُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا وَقَالَ ‏ ‏ابْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ ‏ ‏أَكْبَرُ عِلْمِي وَالَّذِي يَخْطِرُ عَلَى بَالِي ‏ ‏أَنَّ ‏ ‏أَبَا الشَّعْثَاءِ ‏ ‏أَخْبَرَنِي أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ ‏ ‏بِفَضْلِ ‏ ‏مَيْمُونَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cee77f64-2bb5-5b73-a21b-cd253b1c246d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '488', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ بِنْتَ أُمِّ سَلَمَةَ ‏ ‏حَدَّثَتْهُ أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏حَدَّثَتْهَا قَالَتْ ‏ ‏كَانَتْ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلَانِ فِي الْإِنَاءِ الْوَاحِدِ مِنْ الْجَنَابَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cf9b7079-202f-5af8-89a6-ff2cda5a0dcf', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '489', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ مَهْدِيٍّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُا ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ بِخَمْسِ ‏ ‏مَكَاكِيكَ ‏ ‏وَيَتَوَضَّأُ بِمَكُّوكٍ ‏ ‏و قَالَ ‏ ‏ابْنُ الْمُثَنَّى ‏ ‏بِخَمْسِ ‏ ‏مَكَاكِيَّ ‏ ‏و قَالَ ‏ ‏ابْنُ مُعَاذٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏ابْنَ جَبْرٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b5903869-98c0-57c6-84e8-507bee04258f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '490', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏ابْنِ جَبْرٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏ ‏وَيَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏إِلَى خَمْسَةِ ‏ ‏أَمْدَادٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e76a8c68-07a0-54b6-b05b-0d9eda433f7d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '491', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏وَعَمْرُو بْنُ عَلِيٍّ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ الْمُفَضَّلِ ‏ ‏قَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رَيْحَانَةَ ‏ ‏عَنْ ‏ ‏سَفِينَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُغَسِّلُهُ ‏ ‏الصَّاعُ ‏ ‏مِنْ الْمَاءِ مِنْ الْجَنَابَةِ وَيُوَضِّئُهُ ‏ ‏الْمُدُّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9a5c04e0-0f02-571a-8ba9-ab70c9584040', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '492', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏أَبِي رَيْحَانَةَ ‏ ‏عَنْ ‏ ‏سَفِينَةَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏صَاحِبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏وَيَتَطَهَّرُ ‏ ‏بِالْمُدِّ ‏ ‏وَفِي حَدِيثِ ‏ ‏ابْنِ حُجْرٍ ‏ ‏أَوْ قَالَ ‏ ‏وَيُطَهِّرُهُ ‏ ‏الْمُدُّ ‏ ‏و قَالَ ‏ ‏وَقَدْ كَانَ كَبِرَ وَمَا كُنْتُ أَثِقُ بِحَدِيثِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e2ed7c29-c6ef-553e-af0d-89b89641b7ee', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '493', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ صُرَدٍ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏تَمَارَوْا ‏ ‏فِي الْغُسْلِ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بَعْضُ الْقَوْمِ أَمَّا أَنَا فَإِنِّي أَغْسِلُ رَأْسِي كَذَا وَكَذَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا أَنَا فَإِنِّي ‏ ‏أُفِيضُ عَلَى رَأْسِي ثَلَاثَ أَكُفٍّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c7e9ae17-0984-52be-b445-cc829ff920e9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '494', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ صُرَدٍ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ذُكِرَ عِنْدَهُ الْغُسْلُ مِنْ الْجَنَابَةِ فَقَالَ أَمَّا أَنَا ‏ ‏فَأُفْرِغُ عَلَى رَأْسِي ثَلَاثًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3ae8201a-cc39-5c0b-947b-1d53980b175f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '495', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَإِسْمَعِيلُ بْنُ سَالِمٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏وَفْدَ ثَقِيفٍ ‏ ‏سَأَلُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا إِنَّ أَرْضَنَا أَرْضٌ بَارِدَةٌ فَكَيْفَ بِالْغُسْلِ فَقَالَ أَمَّا أَنَا ‏ ‏فَأُفْرِغُ عَلَى رَأْسِي ثَلَاثًا ‏ ‏قَالَ ‏ ‏ابْنُ سَالِمٍ ‏ ‏فِي رِوَايَتِهِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏وَقَالَ ‏ ‏إِنَّ ‏ ‏وَفْدَ ثَقِيفٍ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d99b8dad-03c1-58fe-8b39-729b5e2bb0c8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '496', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ يَعْنِي الثَّقَفِيَّ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اغْتَسَلَ مِنْ جَنَابَةٍ صَبَّ عَلَى رَأْسِهِ ثَلَاثَ ‏ ‏حَفَنَاتٍ ‏ ‏مِنْ مَاءٍ فَقَالَ لَهُ ‏ ‏الْحَسَنُ بْنُ مُحَمَّدٍ ‏ ‏إِنَّ شَعْرِي كَثِيرٌ قَالَ ‏ ‏جَابِرٌ ‏ ‏فَقُلْتُ لَهُ يَا ابْنَ أَخِي كَانَ شَعْرُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرَ مِنْ شَعْرِكَ وَأَطْيَبَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aef7d0aa-e890-50dc-b056-7e1f456ed663', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '497', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَابْنُ أَبِي عُمَرَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي امْرَأَةٌ أَشُدُّ ضَفْرَ رَأْسِي ‏ ‏فَأَنْقُضُهُ ‏ ‏لِغُسْلِ الْجَنَابَةِ قَالَ لَا إِنَّمَا ‏ ‏يَكْفِيكِ أَنْ ‏ ‏تَحْثِيَ ‏ ‏عَلَى رَأْسِكِ ثَلَاثَ ‏ ‏حَثَيَاتٍ ‏ ‏ثُمَّ ‏ ‏تُفِيضِينَ ‏ ‏عَلَيْكِ الْمَاءَ فَتَطْهُرِينَ ‏ ‏و حَدَّثَنَا ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏وَفِي حَدِيثِ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏فَأَنْقُضُهُ ‏ ‏لِلْحَيْضَةِ وَالْجَنَابَةِ فَقَالَ لَا ثُمَّ ذَكَرَ بِمَعْنَى حَدِيثِ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏و حَدَّثَنِيهِ ‏ ‏أَحْمَدُ الدَّارِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏رَوْحِ بْنِ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ مُوسَى ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَقَالَ ‏ ‏أَفَأَحُلُّهُ فَأَغْسِلُهُ مِنْ الْجَنَابَةِ وَلَمْ يَذْكُرْ الْحَيْضَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('249820b5-5cb3-59d8-9fe0-dc5e7726e915', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '498', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَلِيُّ بْنُ حُجْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ عُلَيَّةَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏قَالَ بَلَغَ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَأْمُرُ النِّسَاءَ إِذَا اغْتَسَلْنَ أَنْ ‏ ‏يَنْقُضْنَ ‏ ‏رُءُوسَهُنَّ فَقَالَتْ يَا عَجَبًا ‏ ‏لِابْنِ عَمْرٍو ‏ ‏هَذَا يَأْمُرُ النِّسَاءَ إِذَا اغْتَسَلْنَ أَنْ يَنْقُضْنَ رُءُوسَهُنَّ أَفَلَا يَأْمُرُهُنَّ أَنْ يَحْلِقْنَ رُءُوسَهُنَّ لَقَدْ كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ وَلَا أَزِيدُ عَلَى أَنْ أُفْرِغَ عَلَى رَأْسِي ثَلَاثَ إِفْرَاغَاتٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0a681ae2-4f0a-5ba9-95b6-02297794fe79', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '499', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُحَمَّدٍ النَّاقِدُ ‏ ‏وَابْنُ أَبِي عُمَرَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ صَفِيَّةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلَتْ ‏ ‏امْرَأَةٌ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ تَغْتَسِلُ مِنْ حَيْضَتِهَا قَالَ فَذَكَرَتْ أَنَّهُ عَلَّمَهَا كَيْفَ تَغْتَسِلُ ثُمَّ تَأْخُذُ ‏ ‏فِرْصَةً ‏ ‏مِنْ مِسْكٍ ‏ ‏فَتَطَهَّرُ بِهَا قَالَتْ كَيْفَ أَتَطَهَّرُ بِهَا قَالَ ‏ ‏تَطَهَّرِي بِهَا سُبْحَانَ اللَّهِ وَاسْتَتَرَ ‏ ‏وَأَشَارَ لَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏بِيَدِهِ عَلَى وَجْهِهِ قَالَ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَاجْتَذَبْتُهَا إِلَيَّ وَعَرَفْتُ مَا أَرَادَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ تَتَبَّعِي بِهَا أَثَرَ الدَّمِ ‏ ‏و قَالَ ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏فِي رِوَايَتِهِ فَقُلْتُ تَتَبَّعِي بِهَا آثَارَ الدَّمِ ‏ ‏و حَدَّثَنِي ‏ ‏أَحْمَدُ بْنُ سَعِيدٍ الدَّارِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَبَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ أَغْتَسِلُ عِنْدَ الطُّهْرِ فَقَالَ خُذِي ‏ ‏فِرْصَةً ‏ ‏مُمَسَّكَةً ‏ ‏فَتَوَضَّئِي بِهَا ثُمَّ ‏ ‏ذَكَرَ نَحْوَ حَدِيثِ ‏ ‏سُفْيَانَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ba70cf9e-c0e8-55f2-aeda-efbfb8596c85', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '500', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ الْمُهَاجِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَفِيَّةَ ‏ ‏تُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَسْمَاءَ ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ غُسْلِ الْمَحِيضِ فَقَالَ ‏ ‏تَأْخُذُ إِحْدَاكُنَّ مَاءَهَا ‏ ‏وَسِدْرَتَهَا ‏ ‏فَتَطَهَّرُ فَتُحْسِنُ الطُّهُورَ ثُمَّ تَصُبُّ عَلَى رَأْسِهَا فَتَدْلُكُهُ دَلْكًا شَدِيدًا حَتَّى تَبْلُغَ ‏ ‏شُؤُونَ ‏ ‏رَأْسِهَا ثُمَّ تَصُبُّ عَلَيْهَا الْمَاءَ ثُمَّ تَأْخُذُ ‏ ‏فِرْصَةً ‏ ‏مُمَسَّكَةً ‏ ‏فَتَطَهَّرُ بِهَا فَقَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏وَكَيْفَ ‏ ‏تَطَهَّرُ بِهَا فَقَالَ سُبْحَانَ اللَّهِ ‏ ‏تَطَهَّرِينَ بِهَا فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَأَنَّهَا تُخْفِي ذَلِكَ ‏ ‏تَتَبَّعِينَ أَثَرَ الدَّمِ وَسَأَلَتْهُ عَنْ غُسْلِ الْجَنَابَةِ فَقَالَ تَأْخُذُ مَاءً ‏ ‏فَتَطَهَّرُ فَتُحْسِنُ الطُّهُورَ ‏ ‏أَوْ تُبْلِغُ الطُّهُورَ ‏ ‏ثُمَّ تَصُبُّ عَلَى رَأْسِهَا فَتَدْلُكُهُ حَتَّى تَبْلُغَ ‏ ‏شُؤُونَ ‏ ‏رَأْسِهَا ثُمَّ ‏ ‏تُفِيضُ ‏ ‏عَلَيْهَا الْمَاءَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏نِعْمَ النِّسَاءُ نِسَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏لَمْ يَكُنْ يَمْنَعُهُنَّ الْحَيَاءُ أَنْ يَتَفَقَّهْنَ فِي الدِّينِ ‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏نَحْوَهُ وَقَالَ قَالَ سُبْحَانَ اللَّهِ تَطَهَّرِي بِهَا وَاسْتَتَرَ ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَتْ ‏ ‏أَسْمَاءُ بِنْتُ شَكَلٍ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ كَيْفَ تَغْتَسِلُ إِحْدَانَا إِذَا طَهُرَتْ مِنْ الْحَيْضِ ‏ ‏وَسَاقَ الْحَدِيثَ وَلَمْ يَذْكُرْ فِيهِ غُسْلَ الْجَنَابَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c59b781b-b266-5f2f-8187-1b2b21124409', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '501', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي امْرَأَةٌ أُسْتَحَاضُ فَلَا أَطْهُرُ أَفَأَدَعُ الصَّلَاةَ فَقَالَ لَا إِنَّمَا ‏ ‏ذَلِكِ عِرْقٌ وَلَيْسَ بِالْحَيْضَةِ فَإِذَا أَقْبَلَتْ الْحَيْضَةُ فَدَعِي الصَّلَاةَ وَإِذَا أَدْبَرَتْ فَاغْسِلِي عَنْكِ الدَّمَ وَصَلِّي ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏خَلَفُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏وَكِيعٍ ‏ ‏وَإِسْنَادِهِ ‏ ‏وَفِي حَدِيثِ ‏ ‏قُتَيْبَةَ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏جَاءَتْ ‏ ‏فَاطِمَةُ بِنْتُ أَبِي حُبَيْشِ بْنِ عَبْدِ الْمُطَّلِبِ بْنِ أَسَدٍ ‏ ‏وَهِيَ امْرَأَةٌ مِنَّا ‏ ‏قَالَ ‏ ‏وَفِي حَدِيثِ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏زِيَادَةُ حَرْفٍ تَرَكْنَا ذِكْرَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bcda7f7f-b73b-5335-b668-839d46ddba69', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '502', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحٍ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏اسْتَفْتَتْ ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنِّي أُسْتَحَاضُ فَقَالَ إِنَّمَا ‏ ‏ذَلِكِ ‏ ‏عِرْقٌ ‏ ‏فَاغْتَسِلِي ثُمَّ صَلِّي فَكَانَتْ تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏لَمْ يَذْكُرْ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ ‏ ‏أَنْ تَغْتَسِلَ عِنْدَ كُلِّ صَلَاةٍ وَلَكِنَّهُ شَيْءٌ فَعَلَتْهُ هِيَ ‏ ‏و قَالَ ‏ ‏ابْنُ رُمْحٍ ‏ ‏فِي رِوَايَتِهِ ‏ ‏ابْنَةُ جَحْشٍ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏أُمَّ حَبِيبَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('37cea476-6895-57db-ac12-2e90be72348c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '503', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ الْمُرَادِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏وَعَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ ‏ ‏خَتَنَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَحْتَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏اسْتُحِيضَتْ سَبْعَ سِنِينَ فَاسْتَفْتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذِهِ لَيْسَتْ بِالْحَيْضَةِ وَلَكِنَّ هَذَا ‏ ‏عِرْقٌ ‏ ‏فَاغْتَسِلِي وَصَلِّي ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَكَانَتْ تَغْتَسِلُ فِي ‏ ‏مِرْكَنٍ ‏ ‏فِي حُجْرَةِ أُخْتِهَا ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏حَتَّى تَعْلُوَ حُمْرَةُ الدَّمِ الْمَاءَ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏فَحَدَّثْتُ بِذَلِكَ ‏ ‏أَبَا بَكْرِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏فَقَالَ يَرْحَمُ اللَّهُ ‏ ‏هِنْدًا ‏ ‏لَوْ سَمِعَتْ بِهَذِهِ الْفُتْيَا وَاللَّهِ إِنْ كَانَتْ ‏ ‏لَتَبْكِي لِأَنَّهَا كَانَتْ لَا تُصَلِّي ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو عِمْرَانَ مُحَمَّدُ بْنُ جَعْفَرِ بْنِ زِيَادٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِى ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ اسْتُحِيضَتْ سَبْعَ سِنِينَ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏إِلَى قَوْلِهِ تَعْلُوَ حُمْرَةُ الدَّمِ الْمَاءَ وَلَمْ يَذْكُرْ مَا بَعْدَهُ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏ابْنَةَ جَحْشٍ ‏ ‏كَانَتْ تُسْتَحَاضُ سَبْعَ سِنِينَ ‏ ‏بِنَحْوِ حَدِيثِهِمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
