insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('32cfa887-1a21-5763-a4a9-589dbe14bd45', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '505', '‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ قُرَيْشٍ التَّمِيمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ بَكْرِ بْنِ مُضَرَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّ ‏ ‏أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ ‏ ‏الَّتِي كَانَتْ تَحْتَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏شَكَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الدَّمَ فَقَالَ لَهَا ‏ ‏امْكُثِي قَدْرَ مَا كَانَتْ تَحْبِسُكِ حَيْضَتُكِ ثُمَّ اغْتَسِلِي فَكَانَتْ تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6925db4f-baff-5464-800e-9f694fd68c55', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '506', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ ‏ ‏امْرَأَةً سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ ‏ ‏أَتَقْضِي إِحْدَانَا الصَّلَاةَ أَيَّامَ مَحِيضِهَا فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قَدْ ‏ ‏كَانَتْ إِحْدَانَا تَحِيضُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ لَا تُؤْمَرُ بِقَضَاءٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('54d0c2aa-a387-5cbd-a5ed-0f67424c254f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '507', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّهَا سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏أَتَقْضِي الْحَائِضُ الصَّلَاةَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قَدْ ‏ ‏كُنَّ نِسَاءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحِضْنَ أَفَأَمَرَهُنَّ أَنْ يَجْزِينَ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏تَعْنِي يَقْضِينَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('473e3247-e7a0-5080-8a5c-94b234e7ff24', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '508', '‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ مَا بَالُ الْحَائِضِ تَقْضِي الصَّوْمَ وَلَا تَقْضِي الصَّلَاةَ فَقَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قُلْتُ لَسْتُ ‏ ‏بِحَرُورِيَّةٍ وَلَكِنِّي أَسْأَلُ قَالَتْ كَانَ يُصِيبُنَا ذَلِكَ فَنُؤْمَرُ بِقَضَاءِ الصَّوْمِ وَلَا نُؤْمَرُ بِقَضَاءِ الصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2a6887d4-b815-5e8f-a660-0f9ac4bf1513', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '509', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏أَنَّ ‏ ‏أَبَا مُرَّةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ ‏ ‏تَقُولُ ‏ ‏ذَهَبْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ فَوَجَدْتُهُ ‏ ‏يَغْتَسِلُ ‏ ‏وَفَاطِمَةُ ‏ ‏ابْنَتُهُ تَسْتُرُهُ بِثَوْبٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a49366bf-4959-5d19-b61b-8615404bfa91', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '510', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحِ بْنِ الْمُهَاجِرِ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏أَنَّ ‏ ‏أَبَا مُرَّةَ ‏ ‏مَوْلَى ‏ ‏عَقِيلٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ ‏ ‏حَدَّثَتْهُ أَنَّهُ ‏ ‏لَمَّا كَانَ عَامُ الْفَتْحِ أَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ بِأَعْلَى ‏ ‏مَكَّةَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى غُسْلِهِ فَسَتَرَتْ عَلَيْهِ ‏ ‏فَاطِمَةُ ‏ ‏ثُمَّ أَخَذَ ثَوْبَهُ فَالْتَحَفَ بِهِ ثُمَّ صَلَّى ثَمَانَ رَكَعَاتٍ ‏ ‏سُبْحَةَ ‏ ‏الضُّحَى ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَقَالَ فَسَتَرَتْهُ ابْنَتُهُ ‏ ‏فَاطِمَةُ ‏ ‏بِثَوْبِهِ فَلَمَّا اغْتَسَلَ أَخَذَهُ فَالْتَحَفَ بِهِ ثُمَّ قَامَ فَصَلَّى ثَمَانَ سَجَدَاتٍ وَذَلِكَ ضُحًى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a7f0604b-2b49-5956-9632-9717f6473efb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '511', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى الْقَارِئُ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏وَضَعْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاءً وَسَتَرْتُهُ فَاغْتَسَلَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('67c0b108-8fbc-56ec-93e1-ce82c3d87366', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '512', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏عَنْ ‏ ‏الضَّحَّاكِ بْنِ عُثْمَانَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْظُرُ الرَّجُلُ إِلَى عَوْرَةِ الرَّجُلِ وَلَا الْمَرْأَةُ إِلَى عَوْرَةِ الْمَرْأَةِ وَلَا ‏ ‏يُفْضِي ‏ ‏الرَّجُلُ إِلَى الرَّجُلِ فِي ثَوْبٍ وَاحِدٍ وَلَا ‏ ‏تُفْضِي ‏ ‏الْمَرْأَةُ إِلَى الْمَرْأَةِ فِي الثَّوْبِ الْوَاحِدِ ‏ ‏و حَدَّثَنِيهِ ‏ ‏هَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَمُحَمَّدُ بْنُ رَافِعٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي فُدَيْكٍ ‏ ‏أَخْبَرَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَقَالَا ‏ ‏مَكَانَ عَوْرَةِ عُرْيَةِ الرَّجُلِ وَعُرْيَةِ الْمَرْأَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1bacdcfd-435c-5856-9f5a-ca33db6c9c78', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '513', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏قَالَ هَذَا مَا حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَحَادِيثَ مِنْهَا ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏يَغْتَسِلُونَ عُرَاةً يَنْظُرُ بَعْضُهُمْ إِلَى سَوْأَةِ بَعْضٍ وَكَانَ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَغْتَسِلُ وَحْدَهُ فَقَالُوا وَاللَّهِ مَا يَمْنَعُ ‏ ‏مُوسَى ‏ ‏أَنْ يَغْتَسِلَ مَعَنَا إِلَّا أَنَّهُ آدَرُ قَالَ فَذَهَبَ مَرَّةً يَغْتَسِلُ فَوَضَعَ ثَوْبَهُ عَلَى حَجَرٍ فَفَرَّ الْحَجَرُ بِثَوْبِهِ قَالَ ‏ ‏فَجَمَحَ ‏ ‏مُوسَى ‏ ‏بِإِثْرِهِ يَقُولُ ثَوْبِي حَجَرُ ثَوْبِي حَجَرُ حَتَّى نَظَرَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏إِلَى سَوْأَةِ ‏ ‏مُوسَى ‏ ‏قَالُوا وَاللَّهِ مَا ‏ ‏بِمُوسَى ‏ ‏مِنْ بَأْسٍ فَقَامَ الْحَجَرُ حَتَّى نُظِرَ إِلَيْهِ قَالَ فَأَخَذَ ثَوْبَهُ فَطَفِقَ بِالْحَجَرِ ضَرْبًا قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَاللَّهِ إِنَّهُ بِالْحَجَرِ نَدَبٌ سِتَّةٌ أَوْ سَبْعَةٌ ضَرْبُ ‏ ‏مُوسَى ‏ ‏بِالْحَجَرِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ed6ecaeb-d077-53d3-8b44-75bd8a0b065d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '514', '‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏وَمُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏وَمُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَاللَّفْظُ لَهُمَا ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا وَقَالَ ‏ ‏ابْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُا ‏ ‏لَمَّا بُنِيَتْ ‏ ‏الْكَعْبَةُ ‏ ‏ذَهَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبَّاسٌ ‏ ‏يَنْقُلَانِ حِجَارَةً فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلْ ‏ ‏إِزَارَكَ ‏ ‏عَلَى ‏ ‏عَاتِقِكَ ‏ ‏مِنْ الْحِجَارَةِ فَفَعَلَ ‏ ‏فَخَرَّ ‏ ‏إِلَى الْأَرْضِ ‏ ‏وَطَمَحَتْ ‏ ‏عَيْنَاهُ إِلَى السَّمَاءِ ثُمَّ قَامَ فَقَالَ ‏ ‏إِزَارِي ‏ ‏إِزَارِي فَشَدَّ عَلَيْهِ ‏ ‏إِزَارَهُ ‏ ‏قَالَ ‏ ‏ابْنُ رَافِعٍ ‏ ‏فِي رِوَايَتِهِ عَلَى رَقَبَتِكَ وَلَمْ يَقُلْ عَلَى عَاتِقِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4c099508-5418-5dc5-8ebd-ce8df76f3488', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '515', '‏ ‏و حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ بْنُ إِسْحَقَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْقُلُ مَعَهُمْ الْحِجَارَةَ ‏ ‏لِلْكَعْبَةِ ‏ ‏وَعَلَيْهِ إِزَارُهُ فَقَالَ لَهُ ‏ ‏الْعَبَّاسُ ‏ ‏عَمُّهُ يَا ابْنَ أَخِي لَوْ حَلَلْتَ إِزَارَكَ فَجَعَلْتَهُ عَلَى مَنْكِبِكَ دُونَ الْحِجَارَةِ قَالَ فَحَلَّهُ فَجَعَلَهُ عَلَى مَنْكِبِهِ فَسَقَطَ مَغْشِيًّا عَلَيْهِ قَالَ فَمَا رُئِيَ بَعْدَ ذَلِكَ الْيَوْمِ عُرْيَانًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ca5dff55-3019-5880-9ea9-925ce35006d3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '516', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَحْيَى الْأُمَوِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمِ بْنِ عَبَّادِ بْنِ حُنَيْفٍ الْأَنْصَارِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو أُمَامَةَ بْنُ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏عَنْ ‏ ‏الْمِسْوَرِ بْنِ مَخْرَمَةَ ‏ ‏قَالَ ‏ ‏أَقْبَلْتُ بِحَجَرٍ أَحْمِلُهُ ثَقِيلٍ وَعَلَيَّ ‏ ‏إِزَارٌ ‏ ‏خَفِيفٌ قَالَ فَانْحَلَّ إِزَارِي ‏ ‏وَمَعِيَ الْحَجَرُ لَمْ أَسْتَطِعْ أَنْ أَضَعَهُ حَتَّى بَلَغْتُ بِهِ إِلَى مَوْضِعِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْجِعْ إِلَى ثَوْبِكَ فَخُذْهُ وَلَا تَمْشُوا عُرَاةً ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6ab75c7a-e896-5457-9430-d41cdddc75f8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '517', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَسْمَاءَ الضُّبَعِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَهْدِيٌّ وَهُوَ ابْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏أَرْدَفَنِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ خَلْفَهُ فَأَسَرَّ إِلَيَّ حَدِيثًا لَا أُحَدِّثُ بِهِ أَحَدًا مِنْ النَّاسِ وَكَانَ أَحَبَّ مَا اسْتَتَرَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ ‏ ‏هَدَفٌ ‏ ‏أَوْ ‏ ‏حَائِشُ ‏ ‏نَخْلٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَسْمَاءَ ‏ ‏فِي حَدِيثِهِ ‏ ‏يَعْنِي حَائِطَ نَخْلٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e5a96c6f-9287-5be6-8b12-f4c62ad90e5d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '518', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَيَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ ‏ ‏وَابْنُ حُجْرٍ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرُونَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ وَهُوَ ابْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شَرِيكٍ يَعْنِي ابْنَ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ إِلَى ‏ ‏قُبَاءَ ‏ ‏حَتَّى إِذَا كُنَّا فِي ‏ ‏بَنِي سَالِمٍ ‏ ‏وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَابِ ‏ ‏عِتْبَانَ ‏ ‏فَصَرَخَ بِهِ فَخَرَجَ يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْجَلْنَا الرَّجُلَ فَقَالَ ‏ ‏عِتْبَانُ ‏ ‏يَا رَسُولَ اللَّهِ أَرَأَيْتَ الرَّجُلَ يُعْجَلُ عَنْ امْرَأَتِهِ وَلَمْ ‏ ‏يُمْنِ ‏ ‏مَاذَا عَلَيْهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الْمَاءُ مِنْ الْمَاءِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2e3610aa-f0ff-5b79-8dfd-2b2bd0b75ed1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '519', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّمَا الْمَاءُ مِنْ الْمَاءِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('44330029-66ea-5e1b-ba7f-1fa824b32c0d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '520', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ بْنُ الشِّخِّيرِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْسَخُ ‏ ‏حَدِيثُهُ بَعْضُهُ بَعْضًا كَمَا ‏ ‏يَنْسَخُ ‏ ‏الْقُرْآنُ بَعْضُهُ بَعْضًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5e084054-977f-5a81-acfc-176f66aa46ff', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '521', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَأَرْسَلَ إِلَيْهِ فَخَرَجَ وَرَأْسُهُ يَقْطُرُ فَقَالَ ‏ ‏لَعَلَّنَا أَعْجَلْنَاكَ قَالَ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ إِذَا أُعْجِلْتَ أَوْ ‏ ‏أَقْحَطْتَ ‏ ‏فَلَا غُسْلَ عَلَيْكَ وَعَلَيْكَ الْوُضُوءُ ‏ ‏و قَالَ ‏ ‏ابْنُ بَشَّارٍ ‏ ‏إِذَا أُعْجِلْتَ أَوْ ‏ ‏أُقْحِطْتَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3ad91a5a-a47c-57d5-af16-42cd35dc58fc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '522', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ ‏ ‏يُصِيبُ ‏ ‏مِنْ الْمَرْأَةِ ثُمَّ ‏ ‏يُكْسِلُ ‏ ‏فَقَالَ ‏ ‏يَغْسِلُ مَا أَصَابَهُ مِنْ الْمَرْأَةِ ثُمَّ يَتَوَضَّأُ وَيُصَلِّي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('04dabab2-0487-54ab-b062-69cfba4c537e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '523', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مَحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الْمَلِيِّ ‏ ‏عَنْ ‏ ‏الْمَلِيِّ ‏ ‏يَعْنِي بِقَوْلِهِ الْمَلِيِّ ‏ ‏عَنْ ‏ ‏الْمَلِيِّ ‏ ‏أَبُو أَيُّوبَ ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي الرَّجُلِ يَأْتِي أَهْلَهُ ثُمَّ لَا يُنْزِلُ قَالَ ‏ ‏يَغْسِلُ ذَكَرَهُ وَيَتَوَضَّأُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('78b0579c-c43a-5099-b21b-644a8dfe728a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '524', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏عَنْ ‏ ‏الْحُسَيْنِ بْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَسَارٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏زَيْدَ بْنَ خَالِدٍ الْجُهَنِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَأَلَ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏قَالَ ‏ ‏قُلْتُ أَرَأَيْتَ إِذَا جَامَعَ الرَّجُلُ امْرَأَتَهُ وَلَمْ يُمْنِ قَالَ ‏ ‏عُثْمَانُ ‏ ‏يَتَوَضَّأُ كَمَا يَتَوَضَّأُ لِلصَّلَاةِ وَيَغْسِلُ ذَكَرَهُ قَالَ ‏ ‏عُثْمَانُ ‏ ‏سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏عَنْ ‏ ‏الْحُسَيْنِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَأَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا أَيُّوبَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ سَمِعَ ذَلِكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a4ce8ca7-289a-544e-95b9-55f59a7d571b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '525', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَأَبُو غَسَّانَ الْمِسْمَعِيُّ ‏ ‏ح ‏ ‏و حَدَّثَنَاه ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَمَطَرٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَلَسَ بَيْنَ ‏ ‏شُعَبِهَا ‏ ‏الْأَرْبَعِ ثُمَّ جَهَدَهَا فَقَدْ وَجَبَ عَلَيْهِ الْغُسْلُ ‏ ‏وَفِي حَدِيثِ ‏ ‏مَطَرٍ ‏ ‏وَإِنْ لَمْ يُنْزِلْ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏مِنْ بَيْنِهِمْ بَيْنَ ‏ ‏أَشْعُبِهَا ‏ ‏الْأَرْبَعِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَبَّادِ بْنِ جَبَلَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنِي ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ غَيْرَ أَنَّ فِي حَدِيثِ ‏ ‏شُعْبَةَ ‏ ‏ثُمَّ اجْتَهَدَ وَلَمْ يَقُلْ وَإِنْ لَمْ يُنْزِلْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7e36d96f-3067-533e-9656-6e3d7269f4f9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '526', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِبْدِ اللَّهِ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏وَهَذَا حَدِيثُهُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏قَالَ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏اخْتَلَفَ فِي ذَلِكَ ‏ ‏رَهْطٌ ‏ ‏مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏الْأَنْصَارِيُّونَ ‏ ‏لَا يَجِبُ الْغُسْلُ إِلَّا مِنْ الدَّفْقِ أَوْ مِنْ الْمَاءِ وَقَالَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏بَلْ إِذَا ‏ ‏خَالَطَ ‏ ‏فَقَدْ وَجَبَ الْغُسْلُ قَالَ قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏فَأَنَا ‏ ‏أَشْفِيكُمْ مِنْ ذَلِكَ فَقُمْتُ فَاسْتَأْذَنْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَأُذِنَ لِي فَقُلْتُ لَهَا يَا ‏ ‏أُمَّاهْ ‏ ‏أَوْ يَا أُمَّ الْمُؤْمِنِينَ ‏ ‏إِنِّي أُرِيدُ أَنْ أَسْأَلَكِ عَنْ شَيْءٍ وَإِنِّي ‏ ‏أَسْتَحْيِيكِ فَقَالَتْ لَا ‏ ‏تَسْتَحْيِي أَنْ تَسْأَلَنِي عَمَّا كُنْتَ سَائِلًا عَنْهُ أُمَّكَ الَّتِي وَلَدَتْكَ فَإِنَّمَا أَنَا أُمُّكَ قُلْتُ فَمَا يُوجِبُ الْغُسْلَ قَالَتْ عَلَى الْخَبِيرِ سَقَطْتَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَلَسَ بَيْنَ ‏ ‏شُعَبِهَا ‏ ‏الْأَرْبَعِ وَمَسَّ الْخِتَانُ الْخِتَانَ فَقَدْ وَجَبَ الْغُسْلُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f6a0ae8a-3eb6-5df2-9b7e-fd0a7fe0b240', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '527', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏وَهَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عِيَاضُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏إِنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ يُجَامِعُ أَهْلَهُ ثُمَّ ‏ ‏يُكْسِلُ ‏ ‏هَلْ عَلَيْهِمَا الْغُسْلُ ‏ ‏وَعَائِشَةُ ‏ ‏جَالِسَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَفْعَلُ ذَلِكَ أَنَا وَهَذِهِ ثُمَّ نَغْتَسِلُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c890611-eb2b-5bdf-8507-61f71e2cbf0c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '528', '‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ شُعَيْبِ بْنِ اللَّيْثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏خَارِجَةَ بْنَ زَيْدٍ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْوُضُوءُ مِمَّا مَسَّتْ النَّارُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2fe011fe-62ff-59b1-8a2b-710433de3912', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '529', '‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ إِبْرَاهِيمَ بْنِ قَارِظٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ وَجَدَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَتَوَضَّأُ عَلَى الْمَسْجِدِ فَقَالَ إِنَّمَا أَتَوَضَّأُ مِنْ ‏ ‏أَثْوَارِ ‏ ‏أَقِطٍ ‏ ‏أَكَلْتُهَا لِأَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('751b5a6f-330d-5a56-ad44-18acb84b9d5a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '530', '‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ خَالِدِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏وَأَنَا أُحَدِّثُهُ هَذَا الْحَدِيثَ أَنَّهُ سَأَلَ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏عَنْ الْوُضُوءِ مِمَّا مَسَّتْ النَّارُ ‏ ‏فَقَالَ ‏ ‏عُرْوَةُ ‏ ‏سَمِعْتُ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
