insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae815947-bfdd-50ea-89d7-cd87b356c38e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '532', '‏ ‏و حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏أَخْبَرَنِي ‏ ‏وَهْبُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ ‏ ‏عَرْقًا ‏ ‏أَوْ لَحْمًا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ وَلَمْ يَمَسَّ مَاءً ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa2c2e2e-0063-5654-8ac2-bfa317fb8cc5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '533', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْتَزُّ ‏ ‏مِنْ كَتِفٍ يَأْكُلُ مِنْهَا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9aeefcd0-044b-507e-b0d4-bbab7ff366d7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '534', '‏ ‏حَدَّثَنِي ‏ ‏أَحْمَدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْتَزُّ مِنْ كَتِفِ شَاةٍ فَأَكَلَ مِنْهَا فَدُعِيَ إِلَى الصَّلَاةِ فَقَامَ وَطَرَحَ السِّكِّينَ وَصَلَّى وَلَمْ يَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَحَدَّثَنِي ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a1372c4d-0327-52ce-a43c-ab179206e0d3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '535', '‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏وَحَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ عِنْدَهَا كَتِفًا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('75948e64-2050-53e1-9258-fec1606c250c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '536', '‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏وَحَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي غَطَفَانَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏أَشْهَدُ لَكُنْتُ ‏ ‏أَشْوِي لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَطْنَ ‏ ‏الشَّاةِ ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae01e67e-2702-522f-b280-a62c78001f2f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '537', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ لَبَنًا ثُمَّ دَعَا بِمَاءٍ فَتَمَضْمَضَ وَقَالَ إِنَّ لَهُ دَسَمًا ‏ ‏و حَدَّثَنِي ‏ ‏أَحْمَدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏وَأَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏بِإِسْنَادِ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('48f4fd5b-bca1-5e03-97ea-0da2490244b5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '538', '‏ ‏و حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ عَلَيْهِ ثِيَابَهُ ثُمَّ خَرَجَ إِلَى الصَّلَاةِ فَأُتِيَ بِهَدِيَّةٍ خُبْزٍ وَلَحْمٍ فَأَكَلَ ثَلَاثَ لُقَمٍ ثُمَّ صَلَّى بِالنَّاسِ وَمَا مَسَّ مَاءً ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَطَاءٍ ‏ ‏قَالَ كُنْتُ مَعَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَسَاقَ الْحَدِيثَ بِمَعْنَى حَدِيثِ ‏ ‏ابْنِ حَلْحَلَةَ ‏ ‏وَفِيهِ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏شَهِدَ ذَلِكَ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ صَلَّى وَلَمْ يَقُلْ بِالنَّاسِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b1f447e2-6e8b-5510-86c4-be1e21d57360', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '539', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ فُضَيْلُ بْنُ حُسَيْنٍ الْجَحْدَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ أَبِي ثَوْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَأَتَوَضَّأُ مِنْ لُحُومِ الْغَنَمِ قَالَ ‏ ‏إِنْ شِئْتَ فَتَوَضَّأْ وَإِنْ شِئْتَ فَلَا تَوَضَّأْ قَالَ أَتَوَضَّأُ مِنْ لُحُومِ الْإِبِلِ قَالَ نَعَمْ فَتَوَضَّأْ مِنْ لُحُومِ الْإِبِلِ قَالَ أُصَلِّي فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ قَالَ نَعَمْ قَالَ أُصَلِّي فِي مَبَارِكِ الْإِبِلِ قَالَ لَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ زَكَرِيَّاءَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏وَأَشْعَثَ بْنِ أَبِي الشَّعْثَاءِ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ أَبِي ثَوْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏أَبِي كَامِلٍ ‏ ‏عَنْ ‏ ‏أَبِي عَوَانَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9b3cf825-c174-5be5-baa1-3d977d90b6d2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '540', '‏ ‏و حَدَّثَنِي ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَعَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏شُكِيَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّجُلُ يُخَيَّلُ إِلَيْهِ أَنَّهُ يَجِدُ الشَّيْءَ فِي الصَّلَاةِ قَالَ ‏ ‏لَا يَنْصَرِفُ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏فِي رِوَايَتِهِمَا ‏ ‏هُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b81061a6-78c2-5999-8626-3a5b483b52a7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '541', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وَجَدَ أَحَدُكُمْ فِي بَطْنِهِ شَيْئًا ‏ ‏فَأَشْكَلَ ‏ ‏عَلَيْهِ أَخَرَجَ مِنْهُ شَيْءٌ أَمْ لَا فَلَا يَخْرُجَنَّ مِنْ الْمَسْجِدِ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('285af629-281a-5f5a-9c45-585b643843aa', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '542', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَابْنُ أَبِي عُمَرَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تُصُدِّقَ عَلَى مَوْلَاةٍ ‏ ‏لِمَيْمُونَةَ ‏ ‏بِشَاةٍ فَمَاتَتْ فَمَرَّ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏هَلَّا أَخَذْتُمْ ‏ ‏إِهَابَهَا ‏ ‏فَدَبَغْتُمُوهُ ‏ ‏فَانْتَفَعْتُمْ بِهِ فَقَالُوا إِنَّهَا مَيْتَةٌ فَقَالَ إِنَّمَا حَرُمَ أَكْلُهَا ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَابْنُ أَبِي عُمَرَ ‏ ‏فِي حَدِيثِهِمَا ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cbb0585f-9db0-592c-a5ad-f2a93835aa95', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '543', '‏ ‏و حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏وَحَرْمَلَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ شَاةً مَيْتَةً أُعْطِيَتْهَا مَوْلَاةٌ ‏ ‏لِمَيْمُونَةَ ‏ ‏مِنْ الصَّدَقَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلَّا انْتَفَعْتُمْ بِجِلْدِهَا قَالُوا إِنَّهَا مَيْتَةٌ فَقَالَ إِنَّمَا حَرُمَ أَكْلُهَا ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ الْحُلْوَانِيُّ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏بِنَحْوِ رِوَايَةِ ‏ ‏يُونُسَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
