insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e54ce1f0-1cd9-5a99-b5fb-d1e22169e806', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '547', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ وَعْلَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا ‏ ‏دُبِغَ ‏ ‏الْإِهَابُ ‏ ‏فَقَدْ طَهُرَ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏وَكِيعٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ وَعْلَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏ ‏يَعْنِي حَدِيثَ ‏ ‏يَحْيَى بْنِ يَحْيَى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
